    // Authentic 74-Course BSCpE 2026 Registrar Dataset
        // Authentic 74-Course BSCpE Registrar Dataset Baseline (Single 4-Year Curriculum)
    const OFFICIAL_BASELINE_74_COURSES = [{"row": 1, "year": 1, "term": 1, "col": 1, "code": "CALCONE", "title": "Calculus 1", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": [], "sos": ["I", "-", "-", "-", "I", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "An introductory course covering the core concepts of limit, continuity and differentiability of functions involving one or more variables. This also includes the application of differential calculations in solving problems on optimization, rates of change, related rates, tangents and normals, and approximations; partial differentiation and transcendental curve tracing."}, {"row": 2, "year": 1, "term": 1, "col": 1, "code": "ENGCHEM", "title": "Chemistry for Engineers Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": [], "sos": ["I", "-", "-", "I", "I", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course provides students with core concepts of chemistry that are important in the pratice of engineering profession."}, {"row": 3, "year": 1, "term": 1, "col": 1, "code": "ENGCHLB", "title": "Chemistry for Engineers Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Basic Engineering", "prereqs": [], "sos": ["I", "-", "-", "I", "I", "I", "-", "-", "-", "-", "-", "-", "-"], "desc": "A fundamental laboratory course designed to provide opportunity to observe and apply the principles and theories taught in the chemistry for engineers."}, {"row": 4, "year": 1, "term": 1, "col": 1, "code": "CPEDISC", "title": "Computer Engineering as a Discipline", "units": 1.0, "lec": 1, "lab": 0, "group": "Professional Core", "prereqs": [], "sos": ["-", "-", "-", "I", "-", "-", "I", "-", "I", "I", "-", "-", "-"], "desc": "This course covers discussion about APC\u2019s engineering degrees and curriculum; introduction to engineering profession: common traits of good engineers, engineering disciplines; preparation for an engineering career; engineering licensures, certifications and organizations; and introduction to engineering code of ethics, This will also prepare students how to prepare students for success through engineering design process, ethical decision-making, teamwork, and communicating to diverse audiences."}, {"row": 5, "year": 1, "term": 1, "col": 1, "code": "PROGLOD", "title": "Programming Logic and Design", "units": 2.0, "lec": 1, "lab": 3, "group": "Professional Core", "prereqs": [], "sos": ["I", "I", "I", "-", "-", "-", "-", "-", "-", "-", "I", "-", "I"], "desc": "This is an introductory course in computer programming logic. The student will learn algorithms applicable to all programming languages, including: identifiers, data types, arrays, control structures, modular programming, generating reports, and computer memory concepts. The student will learn to use charts commonly used in business and information processing. Program logic will be developed using flowcharts and pseudo code. Programs will be written using any programming language."}, {"row": 6, "year": 1, "term": 1, "col": 1, "code": "GETHICS", "title": "Ethics", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "I", "-", "-", "-", "I", "-", "-", "-"], "desc": "Ethics deals with principles of ethical behavior in modern society at the level of the person, society, and in interaction with the environment and other shared resources. (CMO 20 s 2013). Morality pertains to the standards of right and wrong that an individual originally picks up from the community. The course discusses the context and principles of ethical behavior in modern society at the level of individual, society, and in interaction with the environment and other shared resources. The course also teaches students to make moral decisions by using dominant moral frameworks and by applying a seven-step moral reasoning model to analyze and solve moral dilemmas.  The course is organized according to the three (3) main elements of the moral experience: (a) agent, including context \u2014 cultural, communal, and environmental; (b) the act; and (c) reason or framework (for the act)."}, {"row": 7, "year": 1, "term": 1, "col": 1, "code": "PEDUONE", "title": "Physical Education 1", "units": 2.0, "lec": 2, "lab": 0, "group": "Institutional", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "A course exposing students to fundamental importance and application of physical fitness in \nskill execution as well as playing individual dual sports according to the rules."}, {"row": 8, "year": 1, "term": 1, "col": 1, "code": "NATSER1", "title": "NSTP 1", "units": 3.0, "lec": 3, "lab": 0, "group": "Institutional", "prereqs": [], "sos": ["-", "-", "-", "I", "-", "-", "-", "-", "-", "I", "-", "-", "-"], "desc": "National Service aims to develop camaraderie and fellowship by participating in various socio/ economic/ political events and projects."}, {"row": 1, "year": 1, "term": 2, "col": 2, "code": "CALCTWO", "title": "Calculus 2", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": ["CALCONE"], "sos": ["I", "-", "-", "-", "I", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "The course introduces the concept of integration and its application to some physical problems such as evaluation of areas, volumes of revolution, force, and work. The fundamental formula and various techniques of integration are taken up and applied to both single single variable and multi-variable functions. The course also includes tracing of functions of two variables for a bette appreciation of the interpretation of the double and triple integration as vlume of a three-dimensional region bounded by two or more surfaces."}, {"row": 2, "year": 1, "term": 2, "col": 2, "code": "PHYENLC", "title": "Physics for Engineers Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": ["CALCONE"], "sos": ["I", "-", "-", "I", "I", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course covers vectors; kinematics; dynamics; work, energy, and power, impluse and momentum; rotation; dynamics of rotations; elasticity; and oscillation. Fluids; thermal expansion, thermal stress; heat transfer; calorimetry; waves; electrostatic; electricity; magnetism; optics; image formation by plane and curved mirrors; and image formation by thin lenses."}, {"row": 3, "year": 1, "term": 2, "col": 2, "code": "PHYENLB", "title": "Physics for Engineers Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Basic Engineering", "prereqs": ["CALCONE"], "sos": ["I", "-", "-", "I", "I", "I", "-", "-", "-", "-", "-", "-", "-"], "desc": "A fundamental laboratory course designed to provide opportunity to observe and apply the principles and theories taught in the physics  for engineers."}, {"row": 4, "year": 1, "term": 2, "col": 2, "code": "OBJPROG", "title": "Object Oriented Programming", "units": 2.0, "lec": 1, "lab": 3, "group": "Professional Core", "prereqs": ["PROGLOD"], "sos": ["I", "I", "I", "-", "-", "-", "-", "-", "-", "-", "I", "-", "I"], "desc": "Introduces the fundamental concepts of programming from an object oriented perspective. Topics are drawn from classes and objects, abstraction, encapsulation, data types, calling methods and passing parameters, decisions, loops, arrays and collections, documentation, testing and debugging, exceptions, design issues, inheritance, and polymorphic variables and methods. The course emphasizes modern software engineering and design principles."}, {"row": 5, "year": 1, "term": 2, "col": 2, "code": "PHILHIS", "title": "Readings in Philippine History", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "I", "-", "-", "-", "I", "-", "-", "-"], "desc": "The course aims to expose students to different facets of Philippine history through the lens of eyewitnesses. Rather than rely on secondary materials such as textbooks, which is the usual approach in teaching Philippine history, different types of primary sources will be used \u2014 written (qualitative and quantitative), oral, visual, audio-visual digital \u2014 covering various aspects of Philippine life (political, economic, social, cultural). Students are expected to analyze the selected readings contextually and in terms of content (stated and implied). The end goal is to enable students to understand and appreciate our rich past by deriving insights from those who were actually present at the time of the event."}, {"row": 6, "year": 1, "term": 2, "col": 2, "code": "PEDUTWO", "title": "Physical Education 2", "units": 2.0, "lec": 2, "lab": 0, "group": "Institutional", "prereqs": ["PEDUONE"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "A course exposing students to the rudiments of social ballroom dancing, folk dances, modern dances and recreational dances. Students express their feelings and emotions through movements disciplined by rhythm."}, {"row": 8, "year": 1, "term": 2, "col": 2, "code": "NATSER2", "title": "NSTP 2", "units": 3.0, "lec": 3, "lab": 0, "group": "Institutional", "prereqs": ["NATSER1"], "sos": ["-", "-", "-", "I", "-", "-", "-", "-", "-", "I", "-", "-", "-"], "desc": "National Service aims to develop camaraderie and fellowship by participating in various socio/ economic/ political events and projects."}, {"row": 1, "year": 1, "term": 3, "col": 3, "code": "ENGDATA", "title": "Engineering Data Analysis", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": ["CALCONE"], "sos": ["I", "I", "I", "-", "I", "I", "-", "-", "-", "-", "I", "-", "-"], "desc": "This course is designed for undergraduate engineering students with emphasis on problem solving realted to societal issues that engineers and scientists are called upon to solve. It introduces different method for a given situation. The relationship of probability to statistics is also discussed, providing students with the tools they need to understand how \"chance\" plays a role in statistical analysis. Probability distributions of random variables and their uses are also considered, along  with a discussion of linear functions of random variables within the context of their application to data analysis and inference. The course also incldes estimation techniques for unknown parameters; hypothesis testing used in making inferences from sample to population; inference for regression parameters and build models for estimating means and predicting future values of key variables under study. Finally, statistically based experiments are discussed with the aid of statistical software."}, {"row": 2, "year": 1, "term": 3, "col": 3, "code": "ELECIRK", "title": "Fundamentals of Electrical Circuits Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Allied", "prereqs": ["PHYENLC", "PHYENLB"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course introduces the fundamental concepts, circuit laws, theorems and techniques used in electrical circuit analysis and transient analysis, as well as its application. The course covers circuit topologies and DC excitations, transient response, AC response, and polyphase circuits. The use of computer software for circuit simulation and design are emphasized to expose students to computer-based tools."}, {"row": 3, "year": 1, "term": 3, "col": 3, "code": "CRKTLAB", "title": "Fundamentals of Electrical Circuits Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Allied", "prereqs": ["PHYENLC", "PHYENLB"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course allows the students to verify the laws and theorems discussed in Fundamentals of Electrical Circuits (lecture) through simulation, experimentation and project construction. The course topics include experimental determination of the characteristics of the different circuit configurations (series, parallel, series/parallel, delta, and wye), electrical power, Ohm's Law, Kirchhoff's Voltage and Current Laws, Superposition Theorem, Thevenin's Equivalent circuit, and maximum power transfer. The use of computer software for circuit simulation and design are used as basis in verifying expermental results and to expose students to computer-based tools."}, {"row": 4, "year": 1, "term": 3, "col": 3, "code": "ECONOMC", "title": "Engineering Economics", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": [], "sos": ["E", "-", "-", "-", "E", "-", "-", "-", "-", "-", "-", "I", "-"], "desc": "This course covers concepts of the time value of money and equivalence; basic economy study methods; decisions under certainty; decisions recognizing risk; and decisions admitting uncertainty."}, {"row": 5, "year": 1, "term": 3, "col": 3, "code": "DATSTRC", "title": "Data Structures and Algorithms", "units": 2.0, "lec": 1, "lab": 3, "group": "Professional Core", "prereqs": ["OBJPROG"], "sos": ["E", "E", "I", "-", "-", "-", "-", "-", "-", "-", "E", "-", "I"], "desc": "Solving computational problems that involve manipulating collections of data, study a core set of data abstractions, data structures, and algorithms that provide a foundation for writing efficient programs."}, {"row": 6, "year": 1, "term": 3, "col": 3, "code": "MATWORL", "title": "Mathematics for the Modern World", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "Official APC School of Engineering curriculum course: Mathematics for the Modern World. Focuses on outcomes-based competencies aligned with CHED CMO No. 92, s. 2017."}, {"row": 7, "year": 1, "term": 3, "col": 3, "code": "PEDUTRI", "title": "Physical Education 3", "units": 2.0, "lec": 2, "lab": 0, "group": "Institutional", "prereqs": ["PEDUTWO"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "A course exposing students in playing team sports, in enhancing fundamental skills, and in \nbasic rules of the  game."}, {"row": 1, "year": 2, "term": 1, "col": 4, "code": "DISCMAT", "title": "Discrete Mathematics", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": ["CALCTWO"], "sos": ["I", "-", "-", "-", "-", "-", "-", "-", "-", "-", "I", "-", "-"], "desc": "This course deals with logic, sets, proofs, growth of functions, theory of numbers, counting techniques, trees and graph theory."}, {"row": 2, "year": 2, "term": 1, "col": 4, "code": "DIEQUAT", "title": "Differential Equations", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": ["CALCTWO"], "sos": ["I", "-", "-", "-", "I", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course is intended for all engineering students to have a firm foundation on differential equations in preparation for their degree-specific advanced mathematical courses. It covers first order differential equations, nth order linear differential equations and systems of first order linear differential equations. It also introduces the concept of Laplace Transforms in solving differential equations. The students are expected to be able to recognize different kinds of differential equations, determine existence and uniqueness of solution, select the appropriate methods of solution and interpret the obtained solution. Students are also expected to relate differential equations to various practical engineering and scientific problems as well as employ computer technology in solving and verifying solutions."}, {"row": 3, "year": 2, "term": 1, "col": 4, "code": "USERINX", "title": "User Interface and User Experience", "units": 3.0, "lec": 1, "lab": 3, "group": "Professional Core", "prereqs": ["ELECIRK", "CRKTLAB"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course introduces the LabVIEW environment, its features, dataflow programming, and common LabVIEW architectures. This course is the fastest way to become productive with LabVIEW. It prepares the student to develop test and measurement, data acquisition, instrument control, data logging and measurement analysis applications using LabVIEW. The hands-on format of the course enables student to quickly apply skills learned in the course to your application."}, {"row": 4, "year": 2, "term": 1, "col": 4, "code": "OPRSYST", "title": "Operating Systems", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["DATSTRC"], "sos": ["E", "-", "E", "-", "-", "-", "-", "-", "-", "-", "E", "-", "I"], "desc": "This course includes different policies and strategies used by an operating system. Topics include operating systems structures, process management, storage management, file management and distributed systems."}, {"row": 5, "year": 2, "term": 1, "col": 4, "code": "MOBCAPP", "title": "Mobile Code Technology and Application", "units": 3.0, "lec": 1, "lab": 3, "group": "Professional Core", "prereqs": ["OBJPROG"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "The course will focus on the fundamental concepts and techniques of mobile programming, design and development related to mobile applications. This will includes mobile operating system, device capabilities and coding techniques using android technology."}, {"row": 6, "year": 2, "term": 1, "col": 4, "code": "PEDUFOR", "title": "Physical Education 4", "units": 2.0, "lec": 2, "lab": 0, "group": "Institutional", "prereqs": ["PEDUTRI"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "A course exposing students to recreational activities  in the form of Bowling and /or Ice skating held in areas offering recreational and amusement facilities outside of the school premises."}, {"row": 7, "year": 2, "term": 1, "col": 4, "code": "RIZLIFE", "title": "Life and Works of Rizal", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "A comprehensive study and analysis of the life and literary works of Jose Rizal with an emphasis on its impact and relevance to the upliftment of present Philippine society."}, {"row": 1, "year": 2, "term": 2, "col": 5, "code": "NUMERCL", "title": "Numerical Methods", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": ["DIEQUAT"], "sos": ["E", "-", "-", "-", "E", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course covers the concept of numerical analysis and computer software tools in dealing with engineering problems. It includes techniques in finding the roots of an equation, solving systems of linear and non-linear equations, eigenvalue problems, polynomials approximation and interpolation, ordinary and partial differential equations. The Monte-Carlo method, simulation, error propagation and analysis, the methods of least squares and goodness-of-fit tests are also discussed."}, {"row": 2, "year": 2, "term": 2, "col": 5, "code": "ELEXCKT", "title": "Fundamentals of Electronics Circuit Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Allied", "prereqs": ["ELECIRK", "CRKTLAB"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "The course discusses the construction, operation, and characteristics of basic electronics devices sch as junction diodes, bipolar junction transistors, Field Effect Transistors and MOS Field Effect Transistors and oscillators."}, {"row": 3, "year": 2, "term": 2, "col": 5, "code": "ELEXLAB", "title": "Fundamentals of Electronics Circuit Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Allied", "prereqs": ["ELECIRK", "CRKTLAB"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course os the laboratory component of the course Fundamentals of Electronic Circuits (Lecture) that allows students to verify theoretical concepts pertaining to the operation of electronics devices such as the PN junction diodes, BJT and FET and their sibsequent applications to electronics circuits involving reftification, amplification and switching applications. The use of laboratory equipment and apparatus to verify the characteristics of diodes and transistor devices, and their operation in circuits such as rectifiers, voltage regulators, amplifiers, oscillatos and switches are emphasized. Such equipment includes but not limited to the curve tracers, the oscilloscope, signal generator and multi-meters."}, {"row": 4, "year": 2, "term": 2, "col": 5, "code": "PURPCOM", "title": "Purposive Communication", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "I", "E", "I", "-", "-", "-", "-", "-"], "desc": "Purposive Communication is a three-unit course that develops students' communicative competence and enhances their cultural and intercultural awareness through multimodal tasks that provide them opportunities for communicating effectively and appropriately to a multicultural audience in a local or global context. It equips students with tools for critical evaluation of a variety of texts and focuses on the power of language and the impact of images to emphasize the importance of conveying messages responsibly. The knowledge, skills, and insights that students gain from this course may be used in their other academic endeavors, their chosen disciplines, and their future careers as they compose and produce relevant oral, written, audio-visual and/or web-based output for various purposes."}, {"row": 5, "year": 2, "term": 2, "col": 5, "code": "DATMGTS", "title": "Database Management System", "units": 3.0, "lec": 1, "lab": 3, "group": "Professional Core", "prereqs": ["DATSTRC"], "sos": ["-", "E", "E", "E", "E", "-", "-", "-", "-", "-", "E", "E", "E"], "desc": "The course introduces the concepts and definitions of databases, the database environment, database design, development, database security and implementation as well as data warehouses. Students will have practical and hands-on experience in SQL (structured-query-language), which is generally used in the development of database applications as well as management of databases."}, {"row": 6, "year": 2, "term": 2, "col": 5, "code": "ARTAPRE", "title": "Art Appreciation", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "I", "-", "-", "I", "I", "-", "-", "-", "-", "-"], "desc": "Art Appreciation is a three-unit course that develops students' ability to appreciate, analyze, and critique works of art. Through interdisciplinary and multimodal approaches this course equips students with a broad knowledge of the practical, historical, philosophical, and social relevance of the arts in order to hone students' ability to articulate their understanding of the arts. The course also develops students' competency in researching and curating art as well as conceptualizing, mounting, and evaluating art productions. The course aims to develop students' genuine appreciation for Philippine arts by providing them opportunities to explore the diversity and richness and their rootedness in Filipino culture."}, {"row": 8, "year": 2, "term": 2, "col": 5, "code": "ENGCADD", "title": "Computer Aided Drafting", "units": 1.0, "lec": 0, "lab": 3, "group": "Basic Engineering", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "Concepts of computer-aided drafting (CAD); introduction to the CAD environment; terminologies; and the general operating procedures and techniques in entering and executing basic CAD commands."}, {"row": 1, "year": 2, "term": 3, "col": 6, "code": "FDCONTS", "title": "Feedback and Control Systems", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["NUMERCL", "ELEXCKT", "ELEXLAB"], "sos": ["E", "E", "E", "E", "E", "E", "E", "-", "-", "-", "-", "-", "-"], "desc": "The course includes the control devices, equations of a systems and block diagram of systems."}, {"row": 2, "year": 2, "term": 3, "col": 6, "code": "CPEDRAF", "title": "Computer Engineering Drafting and Design", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["ENGCADD", "ELEXCKT", "ELEXLAB"], "sos": ["E", "-", "I", "-", "-", "E", "-", "-", "-", "-", "E", "-", "I"], "desc": "This course focuses on the principles of layout of electrical, electronics, and logic drawings; stressing modern representation used for block diagrams, wiring/assembly, drawings, printed circuit board layouts, and etching."}, {"row": 3, "year": 2, "term": 3, "col": 6, "code": "MIXSIGS", "title": "Fundamentals of Mixed Signals and Sensors", "units": 3.0, "lec": 2, "lab": 3, "group": "Professional Core", "prereqs": ["ELEXCKT", "ELEXLAB"], "sos": ["E", "-", "E", "E", "E", "-", "E", "-", "-", "-", "-", "-", "-"], "desc": "This course covers operational amplifiers, signal converters, power switching devices and the construction and operation of sensors and transducers for converting physical parameters into electrical signals and vice-versa. The course focuses on the application of these devices in developing signal conversion circuits that allows measurement, processing and control of physical parameters by digital processing systems such as a finite state machine or a digital computer. Topics on actuators are also included."}, {"row": 4, "year": 2, "term": 3, "col": 6, "code": "LOGCDES", "title": "Logic Circuit and Design Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["ELEXCKT", "ELEXLAB", "ELECIRK", "CRKTLAB"], "sos": ["E", "E", "I", "-", "-", "-", "I", "-", "-", "-", "-", "-", "-"], "desc": "The course includes design and analysis or digital circuits. This course covers both combinational (synchronous and asynchronous) logic circuits with emphasis on solving digital problems using hardwired structures of the complexity of medium and large-scale integration.", "coreqs": ["LOGICLB"]}, {"row": 5, "year": 2, "term": 3, "col": 6, "code": "LOGICLB", "title": "Logic Circuit and Design Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["DISCMAT", "ELEXLAB"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course focuses on providing hands-on experience in designing digital circuits."}, {"row": 6, "year": 2, "term": 3, "col": 6, "code": "SOFTDES", "title": "Software Design Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["OPRSYST", "DATMGTS", "PURPCOM"], "sos": ["D", "D", "D", "D", "E", "E", "E", "E", "E", "E", "D", "E", "D"], "desc": "This course focuses on programming paradigms and constructs, data structures and use of standard library functions for manipulating them, object-oriented design and the use of modeling languages, testing and software quality concepts, and tradeoffs among different software design methods."}, {"row": 7, "year": 2, "term": 3, "col": 6, "code": "SOFTLAB", "title": "Software Design Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["OPRSYST", "DATMGTS", "PURPCOM"], "sos": ["D", "D", "D", "D", "E", "E", "E", "E", "E", "E", "D", "E", "D"], "desc": "This course focuses on providing hands-on experience in software design."}, {"row": 1, "year": 3, "term": 1, "col": 7, "code": "DIGSPRO", "title": "Digital Signal Processing Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["FDCONTS"], "sos": ["D", "D", "D", "D", "D", "E", "D", "-", "-", "-", "I", "-", "-"], "desc": "The course includes the need for and tradeoffs made when sampling and quantizing a signal; linear, time-invariant system properties; frequency as an analysis domain complementary to time; and filter design."}, {"row": 2, "year": 3, "term": 1, "col": 7, "code": "DIGSLAB", "title": "Digital Signal Processing Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["FDCONTS"], "sos": ["D", "D", "D", "D", "D", "E", "D", "-", "-", "-", "I", "-", "-"], "desc": "This course is designed to provide hands-on activities on different applications of digital signals processing."}, {"row": 3, "year": 3, "term": 1, "col": 7, "code": "CPECGS1", "title": "Cognate / Elective 1 (Web Dev / ML / Robotics)", "units": 3.0, "lec": 2, "lab": 3, "group": "Technical Electives", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course covers ecommerce websites, content management systems (CMS) and social networks. Common web development programming languages and software include Hypertext Markup Language (HTML), Cascading Style Sheets (CSS), JavaScript, PHP, Drupal and MySQL."}, {"row": 4, "year": 3, "term": 1, "col": 7, "code": "EMICROS", "title": "Microprocessors Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["LOGCDES", "LOGICLB"], "sos": ["E", "E", "E", "-", "E", "-", "E", "-", "-", "-", "E", "-", "I"], "desc": "This course provides understanding of architecture of microprocessor-based systems; registers, study of microprocessor operation, assembly language, arithmetic operations, and interfacing."}, {"row": 5, "year": 3, "term": 1, "col": 7, "code": "MCROLAB", "title": "Microprocessors Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["LOGCDES", "LOGICLB"], "sos": ["E", "E", "E", "-", "E", "I", "E", "-", "-", "-", "E", "-", "I"], "desc": "This course provides understanding of architecture of microprocessor-based systems; study of microprocessor operation, assembly language, arithmetic operations, and interfacing"}, {"row": 6, "year": 3, "term": 1, "col": 7, "code": "CPEMETS", "title": "Methods of Research", "units": 2.0, "lec": 2, "lab": 0, "group": "Professional Core", "prereqs": ["ENGDATA", "CPEDRAF", "SOFTDES"], "sos": ["E", "E", "E", "D", "E", "E", "E", "E", "E", "E", "E", "E", "E"], "desc": "This course will provide in-depth understanding of research through exploration of different research methodologies and ethics. It includes qualitative and quantitative research, descriptive and other applicable research methodologies, inferential statistics and introduction to data mining."}, {"row": 7, "year": 3, "term": 1, "col": 7, "code": "INTOHDL", "title": "Intro to HDL", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["LOGCDES", "LOGICLB", "PROGLOD"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "A laboratory course that introduces hardware description language as a tool for designing and testing combinational and sequential circuits. It covers fundamental of concepts of HDL and the basic building blocks of HDL programming."}, {"row": 1, "year": 3, "term": 2, "col": 8, "code": "DATCOMS", "title": "Data and Digital Communications", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["DIGSPRO", "DIGSLAB"], "sos": ["E", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "Official APC School of Engineering curriculum course: Data and Digital Communications. Focuses on outcomes-based competencies aligned with CHED CMO No. 92, s. 2017."}, {"row": 2, "year": 3, "term": 2, "col": 8, "code": "CPECGS2", "title": "Cognate / Elective 2 (C# / Data Analytics)", "units": 3.0, "lec": 2, "lab": 3, "group": "Technical Electives", "prereqs": ["CPECGS1"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course covers programming language using C# as a software tool, in creating computer solutions and applications that can help solve engineering problems."}, {"row": 3, "year": 3, "term": 2, "col": 8, "code": "EMBEDDS", "title": "Embedded System Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["EMICROS", "MCROLAB"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course provides advanced topics in embedded systems design using contemporary practice; interrupt-driven, reactive, real-time, object- oriented, and distributed client/server embedded systems."}, {"row": 4, "year": 3, "term": 2, "col": 8, "code": "EMBEDLB", "title": "Embedded System Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["EMICROS", "MCROLAB"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course will provide hands-on activities designed to advanced topics in embedded systems design using contemporary practice; interrupt-driven, reactive, real-time, object- oriented, and distributed client/server embedded systems."}, {"row": 5, "year": 3, "term": 2, "col": 8, "code": "TECH101", "title": "Technopreneurship 101", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": [], "sos": ["-", "E", "-", "E", "E", "E", "-", "I", "-", "-", "E", "E", "I"], "desc": "The course includes the journey into the world of entrepreneurship with introspection of a business idea into a viable venture. The focus is on unleashing the entrepreneurial spirit in each individual."}, {"row": 6, "year": 3, "term": 2, "col": 8, "code": "EXCOMP1", "title": "Extensive Communication Competency 1", "units": 3.0, "lec": 3, "lab": 0, "group": "Institutional", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "Topics covered in EXCOMP1 broadly include various social issues that are related to the students\u2019 interests. However, a common theme will be observed in the process of instruction as deemed relevant to the student\u2019s program. It primarily focuses on enhancing the students\u2019 listening/observation, presentation, and critical thinking skills. This course prepares the students for their research-related courses as it aims at increasing their engagement in discussions about various social issues that are also potential research subject matter."}, {"row": 8, "year": 3, "term": 2, "col": 8, "code": "UNDSELF", "title": "Understanding the Self", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "I", "I", "-", "-", "-"], "desc": "The course deals with the nature of identity, as well as the factors and forces that affect the development and maintenance of personal identity. The directive to Know Oneself has inspired countless and varied ways to comply. Among the questions that everyone has had to grapple with at one time or other is 'Who am l?\" At no other period is this question asked more urgently than in adolescence\u2014 traditionally believed to be a time of vulnerability and great possibilities. Issues of self and identity are among the most critical for the young. This course is intended to facilitate the exploration of the issues and concerns regarding self and identity to arrive at a better understanding of one's self. It strives to meet this goat by stressing the integration of the personal with the academic\u2014contextualizing matters discussed in the classroom and in the everyday experiences of students\u2014making for better learning, generating a new appreciation for the learning process, and developing a more critical and reflective attitude while enabling them to manage and improve their selves to attain a better quality of life. The course is divided into three major parts: The first part seeks to understand the construct of the self from various disciplinal perspectives: philosophy, sociology, anthropology, and psychology\u2014as well as the more traditional division between the East and West\u2014each seeking to provide answers to the difficult but essential question of \"What is the self?\" And raising, among others, the question: \"Is there even such a construct as the self?\""}, {"row": 1, "year": 3, "term": 3, "col": 9, "code": "COMNETS", "title": "Computer Networks and Security Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["DATCOMS"], "sos": ["E", "E", "E", "-", "-", "-", "-", "E", "I", "-", "-", "-", "-"], "desc": "The course includes the basic principles of network architecture, computer network design, services, technologies and network security."}, {"row": 2, "year": 3, "term": 3, "col": 9, "code": "NETSLAB", "title": "Computer Networks and Security Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["DATCOMS"], "sos": ["E", "E", "E", "-", "-", "-", "-", "E", "I", "-", "-", "-", "-"], "desc": "This course provides hands-on laboratory activities on computer networking. It focuses on the configuration of TCP/IP, routers and switches, network security and wireless fidelity."}, {"row": 3, "year": 3, "term": 3, "col": 9, "code": "CPECGS3", "title": "Cognate / Elective 3 (Cloud / Neural Networks)", "units": 3.0, "lec": 2, "lab": 3, "group": "Technical Electives", "prereqs": ["CPECGS2"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "The course includes building and management of a data warehouse application in an online environment, with emphasis on data accessibility using different computing devices, from the desktop to mobile."}, {"row": 4, "year": 3, "term": 3, "col": 9, "code": "CPEDES1", "title": "CPE Practice and Design 1", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["EMICROS", "MCROLAB", "CPEMETS"], "sos": ["D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D"], "desc": "This course is the first course in a two-semester sequence that constitutes the design experience for undergraduate computer engineers. It provides essential ideas, concepts and principles in engineering design process and emphasizes other design issues including engineering standards and multiple constraints as well as effective communication strategies. Students work in teams to develop project proposals for assigned open-ended problems. Students are required to make oral presentations and submit written proposal for their projects."}, {"row": 5, "year": 3, "term": 3, "col": 9, "code": "COMAROR", "title": "Computer Architecture and Organization Lecture", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": ["EMICROS", "MCROLAB"], "sos": ["E", "E", "E", "-", "-", "-", "-", "-", "-", "-", "E", "-", "-"], "desc": "This course includes the study of the evolution of computer architecture and the factors influencing the design of hardware and software elements of computer systems. The focus is on the understanding of the design issues specifically the instruction set architecture and hardware architecture."}, {"row": 6, "year": 3, "term": 3, "col": 9, "code": "ARCORLB", "title": "Computer Architecture and Organization Laboratory", "units": 1.0, "lec": 0, "lab": 3, "group": "Professional Core", "prereqs": ["EMICROS", "MCROLAB"], "sos": ["E", "E", "E", "-", "-", "-", "-", "-", "-", "-", "E", "-", "-"], "desc": "This course will provide hands-on activities designed to focus on the computer hardware issues specifically the instruction set architecture and hardware architecture."}, {"row": 7, "year": 3, "term": 3, "col": 9, "code": "EXCOMP2", "title": "Extensive Communication Competency 2", "units": 3.0, "lec": 3, "lab": 0, "group": "Institutional", "prereqs": ["EXCOMP1"], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "Topics covered in EXCOMP2 focus on Organizational Communication with lessons on Project Management Communication. The students\u2019 program/discipline serves as the primary basis for the theme in the process of instruction. It primarily aims on enhancing the students\u2019 ability to navigate through the various workplace scenarios that require critical communication skills. This course prepares the students for their internship and employment after graduation."}, {"row": 8, "year": 3, "term": 3, "col": 9, "code": "SCITECS", "title": "Science, Technology, and Society", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "I", "-", "I", "-", "-", "-"], "desc": "The course deals with interactions between science and technology and social, cultural, political, and economic contexts that shape and are shaped by them. (CMO No. 20, series of 2013). This interdisciplinary course engages students to confront the realities brought about by science and technology in society. Such realities pervade the personal, the public, and the global aspects of our living and are integral to human development. Scientific knowledge and technological development happen in the context of society with all its socio-political, cultural, economic, and philosophical underpinnings at play. This course seeks to instill reflective knowledge in the students that they are able to live the good life and display ethical decision making in the face of scientific and technological advancement. This course includes mandatory topics on climate change and environmental awareness."}, {"row": 1, "year": 4, "term": 1, "col": 10, "code": "SEMSTRP", "title": "Seminars and Field Trips", "units": 1.0, "lec": 1, "lab": 0, "group": "Professional Core", "prereqs": [], "sos": ["-", "-", "-", "D", "-", "-", "D", "D", "D", "D", "-", "-", "-"], "desc": "The course includes seminars and lecturers on current trends and issues on Computer Engineering developments. Include field trips to different companies and plants dealing with computer system facilities."}, {"row": 2, "year": 4, "term": 1, "col": 10, "code": "HEALTHS", "title": "Basic Occupational Health and Safety", "units": 3.0, "lec": 3, "lab": 0, "group": "Basic Engineering", "prereqs": [], "sos": ["-", "-", "E", "-", "-", "-", "-", "E", "-", "E", "-", "-", "-"], "desc": "This course tackles key Occupational Health and Safety (OSH) concepts, principles and practices that are foundational knowledge requirements applicable in almost all industries. Specifically, it assists learners in identifying the key elements in the OSH situation both here and abroad; determine existing and potential safety and health hazards; identify the range of control measures; discuss pertinent provisions of Philippine laws that refer to occupational safety and health; explain key principles in effectively communicating OSH; identify components of effective OSH programs and demonstrate some skills in identifying hazards and corresponding control measures at the workplace."}, {"row": 3, "year": 4, "term": 1, "col": 10, "code": "CPEDES2", "title": "CPE Practice and Design 2", "units": 2.0, "lec": 0, "lab": 6, "group": "Professional Core", "prereqs": ["CPEDES1"], "sos": ["D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D"], "desc": "This course is the second of the design experience for undergraduate computer engineering students. In this course, students will be expected to build/fabricate their design, test and evaluate the design against their design specifications, and demonstrate a fully functional project to their design review committee. Students make oral presentations and submit final reports documenting their projects."}, {"row": 4, "year": 4, "term": 1, "col": 10, "code": "CPELAWS", "title": "CPE Laws and Practice", "units": 2.0, "lec": 2, "lab": 0, "group": "Professional Core", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "-"], "desc": "This course provides the importance of the professional and ethical responsibilities of practicing computer engineers and the effects of their work on society; the importance of understanding contemporary issues, lifelong learning strategies; and applicable IT laws in the field of computer engineering."}, {"row": 5, "year": 4, "term": 1, "col": 10, "code": "PROFETH", "title": "Professional Ethics", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "I", "-", "-", "-", "I", "-", "-", "-"], "desc": "This course focuses on the study of current ethical standards of business professionals. Participants engage in ethical and legal issues in a variety of settings that they may encounter in the course of their professional careers. Students examine ethical cases and present potential decisions according to ethical decision-making models."}, {"row": 6, "year": 4, "term": 1, "col": 10, "code": "EMERTEC", "title": "Emerging Technologies in CpE", "units": 3.0, "lec": 3, "lab": 0, "group": "Professional Core", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "-", "-", "D", "-", "D"], "desc": "This course is designed to provide flexibility in the curriculum by discussing any emerging technologies applicable to computer engineering."}, {"row": 7, "year": 4, "term": 1, "col": 10, "code": "CONWORL", "title": "The Contemporary World", "units": 3.0, "lec": 3, "lab": 0, "group": "General Education", "prereqs": [], "sos": ["-", "-", "-", "-", "-", "-", "-", "-", "I", "I", "-", "-", "-"], "desc": "This course introduces students to the contemporary world by examining the multifaceted phenomenon of globalization. Using the various disciplines of the social sciences, it examines the economic, social, political, technological, and other transformations that have created an increasing awareness of the interconnectedness of peoples and places around the globe. To this end, the course provides an overview of the various debates in global governance, development, and sustainability. Beyond exposing the student to the world outside the Philippines, it seeks to inculcate a sense of global citizenship and global ethical responsibility. This course includes mandatory topics on population education in the context of population and demography."}, {"row": 1, "year": 4, "term": 2, "col": 11, "code": "INTERN1", "title": "Internship 1: Foundational Practice (240 Hrs)", "units": 6.0, "lec": 0, "lab": 18, "group": "Professional Core", "prereqs": ["CPEDES2"], "sos": ["D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D"], "desc": "INTERN 1 (Foundational Professional Practice) is a full-time industry immersion course in the Computer Engineering program that introduces students to real-world engineering environments by developing foundational professional and technical competencies. Students are exposed to the host organization\u2019s structure, workflows, and operational practices while performing supervised entry-level technical tasks that apply fundamental engineering knowledge using industry tools and systems. The course emphasizes adherence to workplace standards, professional ethics, effective communication, teamwork, and accountability, alongside the preparation of technical documentation and reflective reports that link academic learning to industry experience. Through guided supervision and structured activities, students build essential skills and professional awareness necessary for more advanced responsibilities in subsequent internship terms."}, {"row": 1, "year": 4, "term": 3, "col": 12, "code": "INTERN2", "title": "Internship 2: Industry Immersion (240 Hrs)", "units": 6.0, "lec": 0, "lab": 18, "group": "Professional Core", "prereqs": ["INTERN1"], "sos": ["D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D", "D"], "desc": "INTERN 2 (Intermediate Responsibility) is a full-time industry immersion course that focuses on the application of technical knowledge and the development of problem-solving skills in real-world engineering settings. Students undertake more complex tasks with reduced supervision, actively contributing to ongoing projects while integrating academic concepts into practical solutions. The course emphasizes analytical thinking, participation in technical discussions, use of industry-standard tools and methodologies, and collaboration within multidisciplinary teams. Students are expected to evaluate workplace practices, address technical challenges, and produce structured reports demonstrating their growing competence and professional development."}];

