      const hdrScopeAdmin = document.getElementById('headerSchoolScopeText');
      if (hdrScopeAdmin) hdrScopeAdmin.innerText = 'Academic Architecture';

      const pathPill = document.getElementById('topBarPathPill');
      if (pathPill) pathPill.innerText = 'Schools';

      recordNavigationStep({
        type: 'admin',
        pathText: 'Schools'
      });
