    // =========================================================================
    // DYNAMIC PATH-TO-SIDEBAR AUTO-SYNC
    // Automatically expands and highlights the left sidebar folder tree to match
    // the currently active view and path breadcrumbs (mirroring topBarPathPill).
    // =========================================================================
    function syncSidebarToCurrentPath(schoolId, progCode, viewType, regDocIdx, yearNum, subItemType) {
      // 1. Expand Academic Schools root container
      const schoolsCont = document.getElementById('schoolsFolderCont');
      const schoolsChev = document.getElementById('schoolsFolderChev');
      if (schoolsCont) schoolsCont.classList.remove('hidden');
      if (schoolsChev) {
        schoolsChev.classList.add('rotate-90');
        schoolsChev.classList.remove('rotate-180');
      }

      // 2. Clear previous active highlights across all sidebar nodes
      const allNavItems = document.querySelectorAll('#sidebar button, #sidebar [id^="node-"], #sidebar [id^="nav-"]');
      allNavItems.forEach(el => {
        el.classList.remove('bg-slate-800', 'bg-[#002855]', 'text-white', 'border-l-4', 'border-l-2', 'border-[#E5A823]', 'bg-[#E5A823]/20', 'text-[#E5A823]', 'active-sidebar-node', 'active-rams-btn');
      });

      const schoolIds = (typeof ACADEMIC_SCHOOLS_DATA !== 'undefined' && Array.isArray(ACADEMIC_SCHOOLS_DATA)) 
        ? ACADEMIC_SCHOOLS_DATA.map(s => s.id.toLowerCase()) 
        : ['soe'];

      // If no school and no program -> Admin Institutional Home (Path: Schools)
      if (!schoolId && !progCode) {
        schoolIds.forEach(sId => {
          const sCont = document.getElementById(sId + 'FolderCont');
          const sChev = document.getElementById(sId + 'FolderChev');
          if (sCont) sCont.classList.add('hidden');
          if (sChev) sChev.classList.remove('rotate-90');
        });
        const rootBtn = document.querySelector('#node-schools-root > button');
        if (rootBtn) rootBtn.classList.add('active-sidebar-node');
        return;
      }

      // Resolve schoolId from progCode if needed
      if (!schoolId && progCode) {
        const progInfo = PROGRAM_TO_SCHOOL_MAP[progCode];
        if (progInfo) schoolId = progInfo.schoolId;
      }

      const normSchoolId = schoolId ? String(schoolId).toLowerCase() : 'soe';

      // 3. Open the active school folder; collapse other school folders
      schoolIds.forEach(sId => {
        const sCont = document.getElementById(sId + 'FolderCont');
        const sChev = document.getElementById(sId + 'FolderChev');
        if (sId === normSchoolId) {
          if (sCont) sCont.classList.remove('hidden');
          if (sChev) sChev.classList.add('rotate-90');
          const schoolBtn = document.querySelector(`#node-school-${sId} > button`);
          if (schoolBtn) schoolBtn.classList.add('bg-slate-800', 'text-white');
        } else {
          if (sCont) sCont.classList.add('hidden');
          if (sChev) sChev.classList.remove('rotate-90');
        }
      });

      // If only on EXD homepage (no program active yet)
      if (!progCode) {
        return;
      }

      // Map program code to folder ID
      const progCodeToId = {
        'BSCpE': 'cpe', 'BSCE': 'ce', 'BSECE': 'ece',
        'BSCS': 'cs', 'BSIT': 'it',
        'BMMA': 'mma', 'BSPsych': 'psych',
        'BSBA': 'ba', 'BSA': 'acc',
        'BSArch': 'arch'
      };
      const progId = progCodeToId[progCode] || progCode.toLowerCase();

      // 4. Open the active program folder
      const progCont = document.getElementById(progId + 'FolderCont');
      const progChev = document.getElementById(progId + 'FolderChev');
      if (progCont) progCont.classList.remove('hidden');
      if (progChev) progChev.classList.add('rotate-90');

      // 5. Open Curriculums Management & Revision 2026-2030 ONLY for curriculum-specific views
      const isCurriculumView = ['curriculum-home', 'versioning-history', 'flowchart', 'spreadsheet', 'registrar', 'obe', 'catalog', 'dashboard', 'compliance', 'delegation', 'audit'].includes(viewType) || (!viewType);

      const curricCont = document.getElementById(progId + 'CurricCont');
      const curricChev = document.getElementById(progId + 'CurricChev');
      const revCont = document.getElementById(progId + 'Rev2026Cont');
      const revChev = document.getElementById(progId + 'Rev2026Chev');

      if (isCurriculumView && viewType !== 'workbench' && viewType !== 'homePdProgramView') {
        if (curricCont) curricCont.classList.remove('hidden');
        if (curricChev) curricChev.classList.add('rotate-90');

        if (['flowchart', 'spreadsheet', 'registrar'].includes(viewType)) {
          if (revCont) revCont.classList.remove('hidden');
          if (revChev) revChev.classList.add('rotate-90');
        }
      } else {
        // For non-curriculum views (syllabus, course, workbench), keep curriculum and revision accordions collapsed
        if (curricCont) curricCont.classList.add('hidden');
        if (curricChev) curricChev.classList.remove('rotate-90');

        if (revCont) revCont.classList.add('hidden');
        if (revChev) revChev.classList.remove('rotate-90');

        // Also ensure any other revision folders for this program are hidden
        const subRevs = document.querySelectorAll(`[id^="${progId}Rev"], [id^="${progId}OffDocs"]`);
        subRevs.forEach(el => el.classList.add('hidden'));
        const subChevs = document.querySelectorAll(`[id^="${progId}Rev"][id$="Chev"], [id^="${progId}OffDocs"][id$="Chev"]`);
        subChevs.forEach(el => el.classList.remove('rotate-90', 'rotate-180'));
      }

      // 5b. Expand/Collapse Syllabus & Course Partner Folders
      const sylCont = document.getElementById(`${progId}SyllabusCont`) || document.getElementById('cpeSyllabusCont');
      const sylChev = document.getElementById(`${progId}SyllabusChev`) || document.getElementById('cpeSyllabusChev');
      const crsCont = document.getElementById(`${progId}CourseCont`) || document.getElementById('cpeCourseCont');
      const crsChev = document.getElementById(`${progId}CourseChev`) || document.getElementById('cpeCourseChev');

      if (viewType === 'syllabus') {
        if (sylCont) sylCont.classList.remove('hidden');
        if (sylChev) {
          sylChev.classList.add('rotate-90');
          sylChev.classList.remove('rotate-180');
        }
      } else {
        if (sylCont) sylCont.classList.add('hidden');
        if (sylChev) {
          sylChev.classList.remove('rotate-90');
          sylChev.classList.remove('rotate-180');
        }
      }

      if (viewType === 'course') {
        if (crsCont) crsCont.classList.remove('hidden');
        if (crsChev) {
          crsChev.classList.add('rotate-90');
          crsChev.classList.remove('rotate-180');
        }
      } else {
        if (crsCont) crsCont.classList.add('hidden');
        if (crsChev) {
          crsChev.classList.remove('rotate-90');
          crsChev.classList.remove('rotate-180');
        }
      }

      // 6. Check for Year-level targeting (Unified Synchronous State Machine)
      const effectiveYear = (yearNum !== undefined && yearNum !== null)
        ? yearNum
        : (['spreadsheet', 'flowchart', 'registrar'].includes(viewType) && window.currentSidebarYear ? window.currentSidebarYear : null);

      if (effectiveYear) {
        window.currentSidebarYear = effectiveYear;
        const clampedYear = Math.max(1, Math.min(4, parseInt(effectiveYear, 10) || 1));
        const targetOrd = 'Y' + clampedYear;
        const yearOrdinals = ['Y1', 'Y2', 'Y3', 'Y4'];

        yearOrdinals.forEach(ord => {
          const yCont = document.getElementById(`${progId}${ord}Cont`);
          const yChev = document.getElementById(`${progId}${ord}Chev`);
          if (ord === targetOrd) {
            if (yCont) {
              yCont.classList.remove('hidden');
              if (viewType === 'registrar') {
                // Ensure Year Official Documents container is expanded
                const offDocsYearCont = document.getElementById(`${progId}OffDocs${targetOrd}Cont`);
                const offDocsYearChev = document.getElementById(`${progId}OffDocs${targetOrd}Chev`);
                if (offDocsYearCont) offDocsYearCont.classList.remove('hidden');
                if (offDocsYearChev) {
                  offDocsYearChev.classList.add('rotate-90');
                  offDocsYearChev.classList.remove('rotate-180');
                }

                // Clear direct flowchart/spreadsheet highlights in year container
                yCont.querySelectorAll('button').forEach(btn => {
                  if (btn.getAttribute('onclick')?.includes('openFlowchartForYear') || btn.getAttribute('onclick')?.includes('openSpreadsheetForYear')) {
                    btn.classList.remove('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
                  }
                });

                // Highlight active document in year official documents list
                if (offDocsYearCont) {
                  const targetDocIdx = parseInt(regDocIdx || 1, 10);
                  offDocsYearCont.querySelectorAll('button').forEach(btn => {
                    const oc = btn.getAttribute('onclick') || '';
                    if (oc.includes(`'registrar', ${targetDocIdx}`) || oc.includes(`"registrar", ${targetDocIdx}`) || oc.includes(`'registrar',${targetDocIdx}`)) {
                      btn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
                      btn.classList.remove('text-slate-400');
                    } else {
                      btn.classList.remove('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
                      btn.classList.add('text-slate-400');
                    }
                  });
                }
              } else {
                const activeType = subItemType || (viewType === 'flowchart' ? 'flowchart' : 'spreadsheet');
                const fnName = activeType === 'flowchart' ? 'openFlowchartForYear' : 'openSpreadsheetForYear';
                yCont.querySelectorAll('button').forEach(btn => {
                  if (btn.getAttribute('onclick')?.includes(fnName)) {
                    btn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
                  } else {
                    btn.classList.remove('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
                  }
                });
              }
            }
            if (yChev) {
              yChev.classList.add('rotate-90');
              yChev.classList.remove('rotate-180');
            }
          } else {
            if (yCont) yCont.classList.add('hidden');
            if (yChev) {
              yChev.classList.remove('rotate-90', 'rotate-180');
            }
          }
        });
      } else {
        // Clear active year for program-level views
        window.currentSidebarYear = null;

        // Highlight active leaf node for program-level views
        if (viewType === 'workbench' || viewType === 'homePdProgramView') {
          const progBtn = document.querySelector(`#node-prog-${progId} > button`);
          if (progBtn) progBtn.classList.add('bg-slate-800', 'text-white', 'border-l-2', 'border-[#E5A823]');
        } else if (viewType === 'curriculum-home') {
          const curBtn = document.querySelector(`#node-${progId}-curriculums > button`);
          if (curBtn) curBtn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
        } else if (viewType === 'versioning-history') {
          const vhBtn = document.getElementById('nav-versioning-history');
          if (vhBtn) vhBtn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
        } else if (!viewType || viewType === 'flowchart') {
          const fcBtn = document.getElementById(`nav-${progId}-flowchart`);
          if (fcBtn) fcBtn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
        } else if (viewType === 'spreadsheet' || viewType === 'catalog') {
          const ssBtn = document.getElementById(`nav-${progId}-spreadsheet`);
          if (ssBtn) ssBtn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
        } else if (viewType === 'dashboard' || viewType === 'compliance') {
          const dbBtn = document.getElementById(`nav-${progId}-dashboard`);
          if (dbBtn) dbBtn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
        } else if (viewType === 'registrar') {
          const offDocsCont = document.getElementById(progId + 'OffDocsCont');
          const offDocsChev = document.getElementById(progId + 'OffDocsChev');
          if (offDocsCont) offDocsCont.classList.remove('hidden');
          if (offDocsChev) offDocsChev.classList.add('rotate-90');
          const docBtn = document.getElementById(`nav-${progId}-regdoc-${regDocIdx || 1}`);
          if (docBtn) docBtn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
        } else if (viewType === 'syllabus') {
          const sylvBtn = document.getElementById(`nav-${progId}-syllabus`);
          if (sylvBtn) sylvBtn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
        } else if (viewType === 'course') {
          const crsBtn = document.getElementById(`nav-${progId}-course`);
          if (crsBtn) crsBtn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
        } else if (['obe', 'delegation', 'audit'].includes(viewType)) {
          const toolBtn = document.getElementById(`nav-${progId}-${viewType}`);
          if (toolBtn) toolBtn.classList.add('bg-[#E5A823]/20', 'text-[#E5A823]', 'font-bold', 'border-l-2', 'border-[#E5A823]');
        }

        // 7. Collapse all year accordions (Y1–Y4) when on a program-level view
        const yearOrdinals = ['Y1', 'Y2', 'Y3', 'Y4'];
        yearOrdinals.forEach(ord => {
          const yCont = document.getElementById(`${progId}${ord}Cont`);
          const yChev = document.getElementById(`${progId}${ord}Chev`);
          if (yCont) yCont.classList.add('hidden');
          if (yChev) { yChev.classList.remove('rotate-90', 'rotate-180'); }
        });
      }
    }

    function goToProgramPd(progCode) {
      // Ensure folder accordion expands if currently collapsed
      const progCodeToId = {
        'BSCpE': 'cpe', 'BSCE': 'ce', 'BSECE': 'ece',
        'BSCS': 'cs', 'BSIT': 'it',
        'BMMA': 'mma', 'BSPsych': 'psych',
        'BSBA': 'ba', 'BSA': 'acc',
        'BSArch': 'arch'
      };
      const progId = progCodeToId[progCode] || String(progCode).toLowerCase();
      const folderCont = document.getElementById(progId + 'FolderCont');
      const folderChev = document.getElementById(progId + 'FolderChev');
      if (folderCont && folderCont.classList.contains('hidden')) {
        folderCont.classList.remove('hidden');
        if (folderChev) folderChev.classList.add('rotate-90');
      }

      selectProgram(progCode, 'homePdProgramView');
    }
    window.goToProgramPd = goToProgramPd;

    function goToSchoolExd(schoolId) {
      const normId = String(schoolId).toLowerCase();

      // ── RBAC GUARD: Tier 3 (Executive Director) or above ONLY ───────────────
      const _role = currentActiveRole || 'admin';
      if (_role === 'pd' || _role === 'p' || _role === 'faculty' || _role === 'f') {
        if (typeof showToast === 'function') {
          showToast('⛔ Access Restricted: School Overview is reserved for Executive Director authority.');
        }
        // Expand the school folder accordion so they can reach their program
        const soeCont = document.getElementById('soeFolderCont');
        const soeChev = document.getElementById('soeFolderChev');
        if (soeCont && soeCont.classList.contains('hidden')) {
          soeCont.classList.remove('hidden');
          if (soeChev) soeChev.classList.add('rotate-90');
        }
        return;
      }
      if ((_role === 'exd' || _role === 'x') && normId !== 'soe') {
        if (typeof showToast === 'function') {
          showToast('⛔ Access Restricted: You only have Executive Director authority over the School of Engineering.');
        }
        return;
      }
      // ── END RBAC GUARD ───────────────────────────────────────────────────────

      renderSchoolOverview(normId);

      const school = ACADEMIC_SCHOOLS_DATA.find(s => s.id.toLowerCase() === normId) || { name: schoolId, bannerTitle: 'SCHOOL OF' };
      const schoolTitle = `${school.bannerTitle || 'SCHOOL OF'} ${school.name || schoolId}`;

      const pathPill = document.getElementById('topBarPathPill');
      if (pathPill) {
        pathPill.innerText = `Schools > ${school.name || schoolId} > EXD`;
      }

      // Auto-sync left sidebar to this school path
      syncSidebarToCurrentPath(normId, null, null);

      if (typeof showToast === 'function') {
        showToast(`Opened ${schoolTitle} Executive Director Homepage.`);
      }

      recordNavigationStep({
        type: 'school',
        schoolId: normId,
        pathText: `Schools > ${school.name || schoolId} > EXD`
      });
    }

