    function switchLoginAccount(email, name, role, avatar, roleKey) {
      const mName = document.getElementById('loginModalName');
      const mEmail = document.getElementById('loginModalEmail');
      const mRole = document.getElementById('loginModalRole');
      const mAvatar = document.getElementById('loginModalAvatar');
      if (mName) mName.innerText = name;
      if (mEmail) mEmail.innerText = email;
      if (mRole) mRole.innerText = role;
      if (mAvatar) mAvatar.innerText = avatar;

      const hName = document.getElementById('sidebarUserName');
      const hEmail = document.getElementById('sidebarUserEmail');
      const sbAvatar = document.getElementById('sidebarUserAvatar');
      if (hName) hName.innerText = name;
      if (hEmail) hEmail.innerText = email;
      if (sbAvatar) sbAvatar.innerText = avatar;

      // Close login modal immediately
      closeLoginModal();

      // Set active role state
      currentActiveRole = roleKey;
      window.currentActiveRole = roleKey;

      const roleSel = document.getElementById('roleSelector');
      if (roleSel && roleKey) {
        roleSel.value = roleKey;
      }

      switchRole(roleKey);

      // Route directly to the role's dedicated homepage
      if (roleKey === 'admin' || roleKey === 'a') {
        window._pendingRouteAfterLogin = null;
        if (typeof deselectSchool === 'function') deselectSchool();
        if (typeof deselectProgram === 'function') deselectProgram();
        syncSidebarToCurrentPath(null, null, null);
        renderAdminOverview();
      } else if (roleKey === 'exd' || roleKey === 'x') {
        renderSchoolOverview('SoE');
      } else if (roleKey === 'pd' || roleKey === 'p') {
        renderProgramOverview('BSCpE');
      } else if (roleKey === 'faculty' || roleKey === 'f') {
        renderProgramOverview('BSCpE');
      } else {
        renderAdminOverview();
      }

      applyRolePermissions();
      if (typeof showToast === 'function') {
        showToast(`Signed in as ${name} (${role})`);
      }
    }

