        html += renderExcelTableBlock('4-Year Flowchart Course Schedule (74 Courses)', headers1, rows1, 1, 'Schedule');
        totalDataRows += rows1.length;
        totalTables++;

        // Table 2: Term-by-Term Units Summary Matrix (12 Terms)
