    function openAssignTaskModal(courseTitle, facultyTitle) {
      const isFaculty = (currentActiveRole === 'faculty' || currentActiveRole === 'f');
      if (isFaculty) {
        const msg = '⛔ Access Restricted: Task delegation is reserved for Program Directors.';
        if (typeof showToastNotification === 'function') showToastNotification(msg);
        else if (typeof showToast === 'function') showToast(msg);
        return;
      }

      const modal = document.getElementById('modalAssignTask');
      if (!modal) return;

      const facultyInput = document.getElementById('assignTaskFacultyTitle');
      const startInput = document.getElementById('assignTaskStartDate');
      const endInput = document.getElementById('assignTaskEndDate');
      const clusterInput = document.getElementById('assignTaskCourseTitle');

      if (facultyInput && facultyTitle) facultyInput.value = facultyTitle;

      let initialCodes = [];
      let targetCluster = courseTitle || 'Hardware & Embedded Systems';

      if (facultyTitle) {
        const existingFac = (window.FACULTY_MEMBERS || []).find(f => f.name.toLowerCase() === facultyTitle.toLowerCase());
        if (existingFac) {
          if (existingFac.cluster) targetCluster = existingFac.cluster;
          if (Array.isArray(existingFac.courses) && existingFac.courses.length > 0) {
            initialCodes = existingFac.courses;
          }
        }
      }
      
      // If courseTitle looks like a comma-separated list of course codes rather than a cluster name
      if (courseTitle && !initialCodes.length && /^[A-Z0-9,\s]+$/.test(courseTitle) && courseTitle.includes(',')) {
        initialCodes = String(courseTitle).split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
        targetCluster = 'Hardware & Embedded Systems';
      }

      if (clusterInput) {
        clusterInput.value = targetCluster;
      }

      // Populate courses checklist
      populateCourseChecklist('assignTaskCoursesChecklist', 'assignTaskSelectedCount', initialCodes);

      // Default start date to today and end date to 90 days from now
      const today = new Date();
      const future = new Date();
      future.setDate(today.getDate() + 90);

      if (startInput && !startInput.value) {
        startInput.value = today.toISOString().split('T')[0];
      }
      if (endInput && !endInput.value) {
        endInput.value = future.toISOString().split('T')[0];
      }

      modal.classList.remove('hidden');
      if (window.spaRouter && typeof window.spaRouter.onModalOpen === 'function') {
        window.spaRouter.onModalOpen('assign-task', { course: courseTitle, faculty: facultyTitle });
      }
    }

    function closeAssignTaskModal() {
      const modal = document.getElementById('modalAssignTask');
      if (modal) modal.classList.add('hidden');
      if (window.spaRouter && typeof window.spaRouter.onModalClose === 'function') {
        window.spaRouter.onModalClose('assign-task');
      }
    }

    function submitAssignTask(event) {
      if (event) event.preventDefault();
      const faculty = document.getElementById('assignTaskFacultyTitle')?.value || 'Faculty Member';
      const cluster = document.getElementById('assignTaskCourseTitle')?.value || 'Hardware & Embedded Systems';
      
      const container = document.getElementById('assignTaskCoursesChecklist');
      let checkedCourses = [];
      if (container) {
        checkedCourses = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value.toUpperCase());
      }
      const courseDesc = checkedCourses.length ? checkedCourses.join(', ') : cluster;
      const start = document.getElementById('assignTaskStartDate')?.value || '';
      const end = document.getElementById('assignTaskEndDate')?.value || '';

      // Update faculty directory record if matching faculty found
      const facObj = (window.FACULTY_MEMBERS || []).find(f => f.name.toLowerCase() === faculty.toLowerCase());
      if (facObj) {
        facObj.cluster = cluster;
        facObj.courses = checkedCourses.length ? checkedCourses : [cluster];
        facObj.status = 'Active';
        try {
          localStorage.setItem('apc_faculty_directory', JSON.stringify(window.FACULTY_MEMBERS));
        } catch (e) {}
        renderFacultyDirectory();
      }

      if (window.DELEGATION_REGISTRY) {
        window.DELEGATION_REGISTRY.push({
          id: 'del-' + Date.now(),
          cluster: cluster,
          faculty: faculty,
          scope: checkedCourses.length ? checkedCourses : [cluster],
          startDate: start || new Date().toISOString().split('T')[0],
          endDate: end || new Date(Date.now() + 30*86400000).toISOString().split('T')[0],
          status: 'pending',
          progress: 0,
          submittedAt: null
        });
        if (typeof renderDelegationCards === 'function') renderDelegationCards();
      }

      if (typeof appendAuditLog === 'function') {
        const role = (() => {
          const sel = document.getElementById('roleSelector');
          const map = { admin: 'System Administrator', exd: 'Executive Director', pd: 'Program Director', faculty: 'Faculty Member' };
          return map[sel ? sel.value : 'pd'] || 'Program Director';
        })();
        const now = new Date();
        const pad = n => String(n).padStart(2, '0');
        const timeStr = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
        const summary = `${role} created cluster delegation "${cluster}" (${checkedCourses.length} courses) at ${timeStr} for BSCpE 2026 Curriculum`;
        const diff = [
          { field: 'Assigned Faculty', old: '(unassigned)', new: faculty },
          { field: 'Assigned Courses', old: 'None', new: courseDesc },
          { field: 'Delegation Validity Period', old: 'None', new: `${start} to ${end}` }
        ];
        appendAuditLog('TASK_DELEGATE', cluster, summary, diff, { faculty, start, end, cluster, courses: checkedCourses });
      }

      closeAssignTaskModal();
      showToastNotification(`Delegation active: ${faculty} authorized for ${checkedCourses.length} courses (${start} to ${end}).`);
    }

    function submitAssignTaskAndOpenSpreadsheet() {
      const faculty = document.getElementById('assignTaskFacultyTitle')?.value || 'Faculty Member';
      const cluster = document.getElementById('assignTaskCourseTitle')?.value || 'Hardware & Embedded Systems';
      
      const container = document.getElementById('assignTaskCoursesChecklist');
      let checkedCourses = [];
      if (container) {
        checkedCourses = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value.toUpperCase());
      }
      const courseDesc = checkedCourses.length ? checkedCourses.join(', ') : cluster;
      const start = document.getElementById('assignTaskStartDate')?.value || '';
      const end = document.getElementById('assignTaskEndDate')?.value || '';

      const facObj = (window.FACULTY_MEMBERS || []).find(f => f.name.toLowerCase() === faculty.toLowerCase());
      if (facObj) {
        facObj.cluster = cluster;
        facObj.courses = checkedCourses.length ? checkedCourses : [cluster];
        facObj.status = 'Active';
        try {
          localStorage.setItem('apc_faculty_directory', JSON.stringify(window.FACULTY_MEMBERS));
        } catch (e) {}
        renderFacultyDirectory();
      }

      if (window.DELEGATION_REGISTRY) {
        window.DELEGATION_REGISTRY.push({
          id: 'del-' + Date.now(),
          cluster: cluster,
          faculty: faculty,
          scope: checkedCourses.length ? checkedCourses : [cluster],
          startDate: start || new Date().toISOString().split('T')[0],
          endDate: end || new Date(Date.now() + 30*86400000).toISOString().split('T')[0],
          status: 'active',
          progress: 10,
          submittedAt: null
        });
        if (typeof renderDelegationCards === 'function') renderDelegationCards();
      }

      if (typeof appendAuditLog === 'function') {
        const role = (() => {
          const sel = document.getElementById('roleSelector');
          const map = { admin: 'System Administrator', exd: 'Executive Director', pd: 'Program Director', faculty: 'Faculty Member' };
          return map[sel ? sel.value : 'pd'] || 'Program Director';
        })();
        const now = new Date();
        const pad = n => String(n).padStart(2, '0');
        const timeStr = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;
        const summary = `${role} created cluster delegation "${cluster}" (${checkedCourses.length} courses) at ${timeStr} for BSCpE 2026 Curriculum`;
        const diff = [
          { field: 'Assigned Faculty', old: '(unassigned)', new: faculty },
          { field: 'Assigned Courses', old: 'None', new: courseDesc },
          { field: 'Delegation Validity Period', old: 'None', new: `${start} to ${end}` },
          { field: 'Spreadsheet Access', old: 'Closed', new: 'Active / Opened' }
        ];
        appendAuditLog('TASK_DELEGATE', cluster, summary, diff, { faculty, start, end, cluster, courses: checkedCourses });
      }

      closeAssignTaskModal();
      showToastNotification(`Delegation granted to ${faculty} (${start} to ${end}). Opening spreadsheet...`);
      openIntegratedSpreadsheet('dashboard');
    }

    // Switch between Graphical Visual Flowchart and Course Table View
    function switchFlowchartViewMode(mode) {
      const diagramCard = document.getElementById('staticDiagramCard');
      const tableContainer = document.getElementById('flowchartTableContainer');
      const btnDiagram = document.getElementById('flowchartModeBtn-diagram');
      const btnTable = document.getElementById('flowchartModeBtn-table');

      if (mode === 'diagram') {
        if (diagramCard) diagramCard.classList.remove('hidden');
        if (tableContainer) tableContainer.classList.add('hidden');

        if (btnDiagram) {
          btnDiagram.className = 'px-3.5 py-1.5 text-xs font-bold bg-[#002855] text-[#E5A823] shadow-xs cursor-pointer transition flex items-center gap-1.5';
        }
        if (btnTable) {
          btnTable.className = 'px-3.5 py-1.5 text-xs font-bold text-slate-700 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-700 cursor-pointer transition flex items-center gap-1.5';
        }

        if (typeof window.renderFlowchartDiagram === 'function') {
          window.renderFlowchartDiagram();
        }
        if (typeof window.drawAllArrows === 'function') {
          setTimeout(window.drawAllArrows, 60);
        }
      } else {
        if (diagramCard) diagramCard.classList.add('hidden');
        if (tableContainer) tableContainer.classList.remove('hidden');

        if (btnDiagram) {
          btnDiagram.className = 'px-3.5 py-1.5 text-xs font-bold text-slate-700 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-700 cursor-pointer transition flex items-center gap-1.5';
        }
        if (btnTable) {
          btnTable.className = 'px-3.5 py-1.5 text-xs font-bold bg-[#002855] text-[#E5A823] shadow-xs cursor-pointer transition flex items-center gap-1.5';
        }

        if (typeof window.renderFlowchartTable === 'function') {
          window.renderFlowchartTable();
        }
      }
    }

