    window.CURRICULUM_MAPS = (function() {
      try {
        const stored = localStorage.getItem('apc_curriculum_maps');
        if (stored) {
          const list = JSON.parse(stored);
          const c27 = list.find(m => m.id === 'CM-BSCpE-2027');
          if (c27) {
            c27.status = 'UNLOCKED DRAFT';
            c27.statusClass = 'bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300 border-amber-300 dark:border-amber-700';
            c27.name = 'BSCpE 2027–2031 Next Year Batch (Unlocked Draft)';
            c27.approvedBy = 'Draft in Progress (Unlocked)';
          } else {
            list.splice(1, 0, DEFAULT_CURRICULUM_MAPS[1]);
          }
          return list;
        }
      } catch(e) {}
      return DEFAULT_CURRICULUM_MAPS;
    })();
    window.currentActiveCurriculumMap = 'CM-BSCpE-2026';

    window.openCurriculumMapTab = function() {
      navigateView('obe');
      setTimeout(() => switchObeTab('hierarchy'), 20);
    };

    window.selectCurriculumMap = function(mapId) {
      window.currentActiveCurriculumMap = mapId;
      renderCurriculumMapHierarchy();
      if (typeof renderPeoCards === 'function') renderPeoCards();
      if (typeof renderSoCards === 'function') renderSoCards();
      if (typeof renderGaCards === 'function') renderGaCards();
      if (typeof renderPeoSoAlignmentTable === 'function') renderPeoSoAlignmentTable();
      if (typeof renderPeoGaAlignmentTable === 'function') renderPeoGaAlignmentTable();
    };

    window.renderCurriculumMapHierarchy = function() {
      const map = (window.CURRICULUM_MAPS || []).find(m => m.id === window.currentActiveCurriculumMap) || window.CURRICULUM_MAPS[0];
      if (!map) return;

      const sel = document.getElementById('curriculumMapSelect');
      if (sel && sel.value !== map.id) sel.value = map.id;

      const tagEl = document.getElementById('curricMapActiveTag');
      if (tagEl) {
        tagEl.textContent = map.status;
        tagEl.className = 'px-2 py-0.5 font-mono text-[10px] font-bold border ' + (map.statusClass || '');
      }

      const titleEl = document.getElementById('curricMapActiveTitle');
      if (titleEl) titleEl.textContent = `${map.name} (${map.id})`;

      const mapVerEl = document.getElementById('curricMapActiveVer');
      if (mapVerEl) mapVerEl.textContent = map.mapRevision;

      // Update flowchart labels
      const gGA = document.getElementById('graphLabelGA');
      if (gGA) gGA.textContent = map.gaVersion;

      const gPEO = document.getElementById('graphLabelPEO');
      if (gPEO) gPEO.textContent = map.peoVersion;

      const gMapRev = document.getElementById('graphLabelMapRev');
      if (gMapRev) gMapRev.textContent = map.mapRevision;

      const gSO = document.getElementById('graphLabelSO');
      if (gSO) gSO.textContent = map.soVersion;

      const gCUR = document.getElementById('graphLabelCUR');
      if (gCUR) gCUR.textContent = map.curriculumVersion;

      // Highlight active batch nodes in flowchart DAG
      const curNodes = [
        { id: 'graphNodeCUR_2026', match: map.id === 'CM-BSCpE-2026' || map.curriculumVersion.includes('2026') },
        { id: 'graphNodeCUR_2027', match: map.id === 'CM-BSCpE-2027' || map.curriculumVersion.includes('2027') },
        { id: 'graphNodeCUR_2025', match: map.id === 'CM-BSCpE-2025' || map.curriculumVersion.includes('2025') }
      ];
      curNodes.forEach(item => {
        const el = document.getElementById(item.id);
        if (!el) return;
        if (item.match) {
          el.className = 'p-2.5 bg-white dark:bg-[#182232] border-2 border-[#002855] dark:border-[#E5A823] text-center shadow-xs transition hover:scale-105 cursor-pointer ring-2 ring-apc-gold opacity-100';
          const badge = el.querySelector('.node-active-badge');
          if (badge) {
            badge.className = 'node-active-badge inline-block mt-0.5 px-1.5 py-0.2 text-[9px] font-mono bg-emerald-100 text-emerald-800 font-bold';
            badge.textContent = 'ACTIVE';
          }
        } else {
          el.className = 'p-2.5 bg-slate-50 dark:bg-[#151D2A] border-2 border-slate-300 dark:border-slate-700 text-center shadow-xs transition hover:scale-105 cursor-pointer opacity-65 hover:opacity-100';
          const badge = el.querySelector('.node-active-badge');
          if (badge) {
            const is2027 = item.id.includes('2027');
            badge.className = 'node-active-badge inline-block mt-0.5 px-1.5 py-0.2 text-[9px] font-mono ' + (is2027 ? 'bg-blue-100 text-blue-800' : 'bg-slate-200 text-slate-600');
            badge.textContent = is2027 ? 'NEXT BATCH' : 'PREV BATCH';
          }
        }
      });

      // Highlight active SO nodes in flowchart
      const soNodes = [
        { id: 'graphNodeSO_2026', match: map.soVersion.includes('2026') },
        { id: 'graphNodeSO_2025', match: map.soVersion.includes('2025') }
      ];
      soNodes.forEach(item => {
        const el = document.getElementById(item.id);
        if (!el) return;
        if (item.match) {
          el.className = 'p-3 bg-white dark:bg-[#182232] border-2 border-[#002855] dark:border-[#E5A823] text-center shadow-xs transition hover:scale-105 cursor-pointer ring-2 ring-apc-gold opacity-100';
          const badge = el.querySelector('.node-active-badge');
          if (badge) {
            badge.className = 'node-active-badge inline-block mt-1 px-1.5 py-0.2 text-[9px] font-mono bg-emerald-100 dark:bg-emerald-900/60 text-emerald-800 dark:text-emerald-300 font-bold';
            badge.textContent = 'ACTIVE';
          }
        } else {
          el.className = 'p-3 bg-slate-50 dark:bg-[#151D2A] border-2 border-slate-300 dark:border-slate-700 text-center shadow-xs transition hover:scale-105 cursor-pointer opacity-65 hover:opacity-100';
          const badge = el.querySelector('.node-active-badge');
          if (badge) {
            badge.className = 'node-active-badge inline-block mt-1 px-1.5 py-0.2 text-[9px] font-mono bg-slate-200 dark:bg-slate-800 text-slate-500';
            badge.textContent = 'PREV BATCH';
          }
        }
      });

      // Highlight active PEO nodes in flowchart
      const peoNodes = [
        { id: 'graphNodePEO_2026', match: map.peoVersion.includes('2026') },
        { id: 'graphNodePEO_2027', match: map.peoVersion.includes('2027') }
      ];
      peoNodes.forEach(item => {
        const el = document.getElementById(item.id);
        if (!el) return;
        if (item.match) {
          el.className = 'p-3 bg-white dark:bg-[#182232] border-2 border-[#002855] dark:border-[#E5A823] text-center shadow-xs transition hover:scale-105 cursor-pointer ring-2 ring-apc-gold opacity-100';
          const badge = el.querySelector('.node-active-badge');
          if (badge) {
            badge.className = 'node-active-badge inline-block mt-1 px-1.5 py-0.2 text-[9px] font-mono bg-emerald-100 dark:bg-emerald-900/60 text-emerald-800 dark:text-emerald-300 font-bold';
            badge.textContent = 'ACTIVE';
          }
        } else {
          el.className = 'p-3 bg-slate-50 dark:bg-[#151D2A] border-2 border-slate-300 dark:border-slate-700 text-center shadow-xs transition hover:scale-105 cursor-pointer opacity-65 hover:opacity-100';
          const badge = el.querySelector('.node-active-badge');
          if (badge) {
            const is2027 = item.id.includes('2027');
            badge.className = 'node-active-badge inline-block mt-1 px-1.5 py-0.2 text-[9px] font-mono ' + (is2027 ? 'bg-blue-100 dark:bg-blue-900/60 text-blue-800 dark:text-blue-300' : 'bg-slate-200 dark:bg-slate-800 text-slate-500');
            badge.textContent = is2027 ? 'NEXT BATCH' : 'PREV BATCH';
          }
        }
      });

      // Update Tier Cards
      const cCurricId = document.getElementById('cardCurricId');
      if (cCurricId) cCurricId.textContent = map.curriculumVersion;

      const cCurricName = document.getElementById('cardCurricName');
      if (cCurricName) cCurricName.textContent = map.curriculumLabel;

      const cCurricStatus = document.getElementById('cardCurricStatus');
      if (cCurricStatus) cCurricStatus.textContent = map.status;

      const cCurricSpan = document.getElementById('cardCurricSpan');
      if (cCurricSpan) {
        if (map.id.includes('2027')) cCurricSpan.textContent = '2027–2031';
        else if (map.id.includes('2025')) cCurricSpan.textContent = '2025–2029';
        else if (map.id.includes('2021')) cCurricSpan.textContent = '2021–2025';
        else cCurricSpan.textContent = '2026–2030';
      }

      const cSoId = document.getElementById('cardSoId');
      if (cSoId) cSoId.textContent = map.soVersion;

      const cSoMapRel = document.getElementById('cardSoMapRel');
      if (cSoMapRel) cSoMapRel.textContent = map.mapRevision;

      const cPeoId = document.getElementById('cardPeoId');
      if (cPeoId) cPeoId.textContent = map.peoVersion;

      const cPeoGaRel = document.getElementById('cardPeoGaRel');
      if (cPeoGaRel) cPeoGaRel.textContent = map.gaVersion;

      const cGaId = document.getElementById('cardGaId');
      if (cGaId) cGaId.textContent = map.gaVersion;

      // Rule checks text
      const r1 = document.getElementById('ruleCheck1');
      if (r1) r1.textContent = `${map.curriculumVersion} >= ${map.soVersion}`;

      const r2 = document.getElementById('ruleCheck2');
      if (r2) r2.textContent = `${map.soVersion} >= ${map.peoVersion}`;

      const r3 = document.getElementById('ruleCheck3');
      if (r3) r3.textContent = `${map.peoVersion} >= ${map.gaVersion}`;

      if (typeof renderFlowGraph === 'function') {
        renderFlowGraph();
      }
    };

    window.populateCurriculumMapSelect = function() {
      const sel = document.getElementById('curriculumMapSelect');
      if (!sel) return;
      sel.innerHTML = (window.CURRICULUM_MAPS || []).map(m => `
        <option value="${m.id}">${m.curriculumVersion} (${m.mapRevision} &bull; ${m.status})</option>
      `).join('');
      if (window.currentActiveCurriculumMap) sel.value = window.currentActiveCurriculumMap;
    };

    window.verifyCurriculumMapRequisites = function() {
      const map = (window.CURRICULUM_MAPS || []).find(m => m.id === window.currentActiveCurriculumMap) || window.CURRICULUM_MAPS[0];
      if (typeof showToast === 'function') {
        showToast(`✓ Requisite Integrity Passed: ${map.curriculumVersion} ➔ ${map.mapRevision} ➔ ${map.soVersion} ➔ ${map.peoVersion} ➔ ${map.gaVersion} satisfies annual batch constraints!`);
      }
    };

    window.updateNewCurricMapPreview = function() {
      const sel = document.getElementById('newCurricMapSelect');
      if (!sel) return;
      const mapId = sel.value;
      const map = (window.CURRICULUM_MAPS || []).find(m => m.id === mapId);
      if (!map) return;
      const ga = document.getElementById('previewModalGa');
      if (ga) ga.textContent = map.gaVersion;
      const peo = document.getElementById('previewModalPeo');
      if (peo) peo.textContent = map.peoVersion;
      const so = document.getElementById('previewModalSo');
      if (so) so.textContent = map.soVersion;
    };

    window.updateNewCurricLineagePreview = function() {
      const prog = document.getElementById('newCurricProgram')?.value || 'BSCpE';
      const startYr = document.getElementById('newCurricStartYear')?.value || '2027';
      const endYr = document.getElementById('newCurricEndYear')?.value || '2031';
      const soSelect = document.getElementById('newCurricSoVersion');
      const peoSelect = document.getElementById('newCurricPeoVersion');
      const gaSelect = document.getElementById('newCurricGaVersion');

      const tagInput = document.getElementById('newCurricVersionTag');
      if (tagInput) tagInput.value = `${prog} ${startYr}`;

      const mapNameInput = document.getElementById('newCurricMapName');
      if (mapNameInput && (!mapNameInput.dataset.manualEdit)) {
        mapNameInput.value = `${prog} ${startYr}–${endYr} Curriculum Map`;
      }

      const pCurric = document.getElementById('previewCurricNode');
      if (pCurric) pCurric.textContent = `${prog} ${startYr}`;

      const pSo = document.getElementById('previewSoNode');
      if (pSo && soSelect) pSo.textContent = soSelect.value;

      const pPeo = document.getElementById('previewPeoNode');
      if (pPeo && peoSelect) pPeo.textContent = peoSelect.value;

      const pGa = document.getElementById('previewGaNode');
      if (pGa && gaSelect) pGa.textContent = gaSelect.value;

      const curricYr = parseInt(startYr, 10);
      const soYrMatch = soSelect ? soSelect.value.match(/\d{4}/) : null;
      const soYr = soYrMatch ? parseInt(soYrMatch[0], 10) : 2026;

      const badge = document.getElementById('newCurricRuleBadge');
      if (badge) {
        if (curricYr >= soYr) {
          badge.className = 'text-emerald-700 dark:text-emerald-400 font-bold';
          badge.textContent = `✓ VALID: Newer links to older/concurrent (${curricYr} >= ${soYr})`;
        } else {
          badge.className = 'text-rose-600 dark:text-rose-400 font-bold';
          badge.textContent = `⚠ WARNING: Older version cannot link to newer (${curricYr} < ${soYr})`;
        }
      }
    };

    window.populateSnapshotBaseMapOptions = function() {
      const sel = document.getElementById('snapshotBaseMapSelect');
      if (!sel) return;
      const maps = window.CURRICULUM_MAPS || [];
      const currentId = window.currentActiveCurriculumMap || (maps[0] ? maps[0].id : '');
      sel.innerHTML = maps.map(m => `
        <option value="${m.id}" ${m.id === currentId ? 'selected' : ''}>
          ${m.id} (${m.name}) &bull; ${m.status}
        </option>
      `).join('');
    };

    window.handleSnapshotBaseMapChange = function() {
      const sel = document.getElementById('snapshotBaseMapSelect');
      if (!sel) return;
      const baseMap = (window.CURRICULUM_MAPS || []).find(m => m.id === sel.value);
      if (!baseMap) return;
      const soSelect = document.getElementById('snapshotSoVer');
      const peoSelect = document.getElementById('snapshotPeoVer');
      const gaSelect = document.getElementById('snapshotGaVer');
      if (soSelect && baseMap.soVersion) soSelect.value = baseMap.soVersion;
      if (peoSelect && baseMap.peoVersion) peoSelect.value = baseMap.peoVersion;
      if (gaSelect && baseMap.gaVersion) gaSelect.value = baseMap.gaVersion;
    };

    window.openSaveCurriculumMapModal = function() {
      const modal = document.getElementById('saveCurriculumMapModal');
      if (!modal) return;
      window.populateSnapshotBaseMapOptions();
      window.handleSnapshotBaseMapChange();
      const role = (window.currentActiveRole || 'admin').toLowerCase();
      const statusSelect = document.getElementById('snapshotMapStatus');
      const activeOption = document.getElementById('snapshotOptionActive');
      const alertEl = document.getElementById('snapshotGovernanceAlert');
      
      if (statusSelect) {
        if (role === 'exd') {
          if (activeOption) {
            activeOption.disabled = false;
            activeOption.textContent = 'ACTIVE BATCH (Executive Director Approved)';
          }
          if (alertEl) {
            alertEl.className = 'p-2.5 bg-emerald-500/10 border border-emerald-500/30 text-[11px] text-emerald-800 dark:text-emerald-300 flex items-start gap-2';
            alertEl.innerHTML = '<span class="text-xs">👑</span><div><span class="font-bold uppercase tracking-wider text-[10px]">ExD Authority:</span> As Executive Director, you can approve and activate curriculum maps directly into <strong>ACTIVE BATCH</strong> status.</div>';
          }
        } else {
          if (activeOption) {
            activeOption.disabled = true;
            activeOption.textContent = 'ACTIVE BATCH (Requires Executive Director Approval)';
          }
          statusSelect.value = 'DRAFT (PENDING EXD APPROVAL)';
          if (alertEl) {
            alertEl.className = 'p-2.5 bg-amber-500/10 border border-amber-500/30 text-[11px] text-amber-800 dark:text-amber-300 flex items-start gap-2';
            alertEl.innerHTML = '<span class="text-xs">⚖️</span><div><span class="font-bold uppercase tracking-wider text-[10px]">Governance Policy:</span> Only the <strong>Executive Director (ExD)</strong> can approve a curriculum map version for <strong>ACTIVE</strong> status. Your submission will be stored as <strong>DRAFT (PENDING EXD APPROVAL)</strong>.</div>';
          }
        }
      }
      modal.classList.remove('hidden');
    };

    window.closeSaveCurriculumMapModal = function() {
      const modal = document.getElementById('saveCurriculumMapModal');
      if (modal) modal.classList.add('hidden');
    };

    window.handleSaveCurriculumMapSubmit = function(e) {
      if (e) e.preventDefault();
      const role = (window.currentActiveRole || 'admin').toLowerCase();
      const name = document.getElementById('snapshotMapName')?.value || 'BSCpE Next Batch Curriculum Map';
      const mapVer = document.getElementById('snapshotMapVersion')?.value || ('Map ' + (new Date().getFullYear() + 1));
      const cVer = document.getElementById('snapshotCurricVer')?.value || ('CPE ' + (new Date().getFullYear() + 1));
      let status = document.getElementById('snapshotMapStatus')?.value || 'DRAFT (PENDING EXD APPROVAL)';
      const soVer = document.getElementById('snapshotSoVer')?.value || 'SO 2026';
      const peoVer = document.getElementById('snapshotPeoVer')?.value || 'PEO 2027';
      const gaVer = document.getElementById('snapshotGaVer')?.value || 'GA 2024';
      const notes = document.getElementById('snapshotMapNotes')?.value || 'Annual curriculum map snapshot.';
      const baseMapId = document.getElementById('snapshotBaseMapSelect')?.value;
      const baseMap = (window.CURRICULUM_MAPS || []).find(m => m.id === baseMapId);

      // Enforce ExD Governance Rule
      if (status === 'ACTIVE BATCH' && role !== 'exd') {
        status = 'DRAFT (PENDING EXD APPROVAL)';
        if (typeof showToast === 'function') {
          showToast('🔒 Only the Executive Director can activate. Saved as Draft pending ExD approval.');
        }
      }

      const yrMatch = cVer.match(/\d{4}/);
      const yr = yrMatch ? yrMatch[0] : (new Date().getFullYear() + 1);
      const newId = `CM-BSCpE-${yr}`;

      // If active, demote previous active maps
      if (status === 'ACTIVE BATCH' && role === 'exd') {
        (window.CURRICULUM_MAPS || []).forEach(m => {
          if (m.status === 'ACTIVE BATCH') {
            m.status = 'PREV BATCH';
            m.statusClass = 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border-slate-300 dark:border-slate-700';
          }
        });
      }

      let statusClass = 'bg-blue-100 dark:bg-blue-950/60 text-blue-800 dark:text-blue-300 border-blue-300 dark:border-blue-700';
      if (status === 'ACTIVE BATCH') {
        statusClass = 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border-emerald-300 dark:border-emerald-700';
      } else if (status.includes('DRAFT')) {
        statusClass = 'bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300 border-amber-300 dark:border-amber-700';
      }

      // Clone from baseMap if available, else from system default
      const coursesToClone = baseMap?.courses ? JSON.parse(JSON.stringify(baseMap.courses)) : JSON.parse(JSON.stringify(window.OFFICIAL_BASELINE_74_COURSES || []));
      const peoSoLinksToClone = baseMap?.peoSoLinks ? JSON.parse(JSON.stringify(baseMap.peoSoLinks)) : JSON.parse(JSON.stringify(window.getPeoSoLinks() || {}));
      const peoGaLinksToClone = baseMap?.peoGaLinks ? JSON.parse(JSON.stringify(baseMap.peoGaLinks)) : JSON.parse(JSON.stringify(window.getPeoGaLinks() || {}));
      const soDefsToClone = baseMap?.soDefs ? JSON.parse(JSON.stringify(baseMap.soDefs)) : JSON.parse(JSON.stringify(window.FLOW_SO_DEFS || []));
      const peoDefsToClone = baseMap?.peoDefs ? JSON.parse(JSON.stringify(baseMap.peoDefs)) : JSON.parse(JSON.stringify(window.FLOW_PEO_DEFS || []));
      const gaDefsToClone = baseMap?.gaDefs ? JSON.parse(JSON.stringify(baseMap.gaDefs)) : JSON.parse(JSON.stringify(window.FLOW_GA_DEFS || []));
      const mvvToClone = baseMap?.mvv ? JSON.parse(JSON.stringify(baseMap.mvv)) : {
        version: 'MVV 2025',
        vision: "Asia Pacific College envisions itself to be the preferred Higher Education Institution bridging academe and industry with its programs founded on the concepts and applications of IT, guided by the core values of integrity, industry, and innovation that works.",
        mission: "Asia Pacific College, powered by education and industry professionals as faculty and a balanced curriculum, aims to provide business and the ICT industry lifelong learning graduates anchored on integrity and professionalism."
      };

      const newEntry = {
        id: newId,
        name: name,
        curriculumVersion: cVer,
        curriculumLabel: `${cVer} (AY ${yr}–${parseInt(yr, 10) + 4})`,
        soVersion: soVer,
        soCount: soDefsToClone.length || 13,
        peoVersion: peoVer,
        peoCount: peoDefsToClone.length || 5,
        gaVersion: gaVer,
        gaCount: gaDefsToClone.length || 9,
        mvvVersion: baseMap?.mvvVersion || 'MVV 2025',
        mapRevision: mapVer,
        status: status,
        statusClass: statusClass,
        createdAt: new Date().toISOString().split('T')[0],
        program: 'BSCpE',
        notes: notes,
        clonedFrom: baseMapId || 'system-baseline',
        approvedBy: (status === 'ACTIVE BATCH') ? 'Executive Director' : 'Draft in Progress',
        courses: coursesToClone,
        peoSoLinks: peoSoLinksToClone,
        peoGaLinks: peoGaLinksToClone,
        soDefs: soDefsToClone,
        peoDefs: peoDefsToClone,
        gaDefs: gaDefsToClone,
        mvv: mvvToClone
      };

      if (!window.CURRICULUM_MAPS) window.CURRICULUM_MAPS = [];
      const existingIdx = window.CURRICULUM_MAPS.findIndex(m => m.id === newId);
      if (existingIdx >= 0) {
        window.CURRICULUM_MAPS[existingIdx] = newEntry;
      } else {
        window.CURRICULUM_MAPS.unshift(newEntry);
      }
      try {
        localStorage.setItem('apc_curriculum_maps', JSON.stringify(window.CURRICULUM_MAPS));
      } catch (err) {}

      window.currentActiveCurriculumMap = newId;
      if (typeof populateCurriculumMapSelect === 'function') populateCurriculumMapSelect();
      closeSaveCurriculumMapModal();
      if (typeof showToast === 'function') {
        showToast(`✓ Saved Curriculum Map '${name}' (${status}) successfully!`);
      }
      renderCurriculumMapHierarchy();
      if (typeof renderVersioningHistoryView === 'function') renderVersioningHistoryView(newId);
    };

    window.approveCurriculumMapVersion = function(mapId) {
      const role = (window.currentActiveRole || 'admin').toLowerCase();
      if (role !== 'exd') {
        if (typeof showToast === 'function') {
          showToast('🔒 Approval Restricted: Only the Executive Director (ExD) can approve a curriculum map to become ACTIVE.');
        }
        return;
      }
      const map = (window.CURRICULUM_MAPS || []).find(m => m.id === mapId);
      if (!map) return;

      // Demote existing active maps
      (window.CURRICULUM_MAPS || []).forEach(m => {
        if (m.status === 'ACTIVE BATCH') {
          m.status = 'PREV BATCH';
          m.statusClass = 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border-slate-300 dark:border-slate-700';
        }
      });

      map.status = 'ACTIVE BATCH';
      map.statusClass = 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 border-emerald-300 dark:border-emerald-700';
      map.approvedBy = 'Executive Director';
      map.approvedAt = new Date().toISOString().split('T')[0];

      try {
        localStorage.setItem('apc_curriculum_maps', JSON.stringify(window.CURRICULUM_MAPS));
      } catch (e) {}

      window.currentActiveCurriculumMap = mapId;
      if (typeof populateCurriculumMapSelect === 'function') populateCurriculumMapSelect();
      if (typeof renderCurriculumMapHierarchy === 'function') renderCurriculumMapHierarchy();
      if (typeof renderVersioningHistoryView === 'function') renderVersioningHistoryView(mapId);
      if (typeof showToast === 'function') {
        showToast(`✓ Map '${map.name}' approved and activated by Executive Director!`);
      }
    };

    window.activateInspectedVersion = function() {
      const mapId = window.currentInspectedVersionId || window.currentActiveCurriculumMap || 'CM-BSCpE-2026';
      if (mapId === 'CM-BSCpE-2027') {
        window.setObeActiveYear('2027');
        navigateView('obe');
        if (typeof showToast === 'function') {
          showToast('Switched to CPE2027 Unlocked Draft map! Full editing enabled.');
        }
        return;
      }
      window.approveCurriculumMapVersion(mapId);
    };

