    window.closeFlowLinkEditor = function() {
      const modal = document.getElementById('flowGraphLinkModal');
      if (modal) modal.classList.add('hidden');
      window.flowEditTarget = { type: null, id: null };
    };

    window.saveFlowLinkEditor = function(e) {
      if (e) e.preventDefault();
      const tr = window.flowEditTarget;
      if (!tr || !tr.type || tr.id === null) {
        window.closeFlowLinkEditor();
        return;
      }

      const peoSoLinks = window.getPeoSoLinks();
      const peoGaLinks = window.getPeoGaLinks();
      const SO_KEYS = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm'];

      if (tr.type === 'course') {
        const c = (window.OFFICIAL_BASELINE_74_COURSES || []).find(course => course.code === tr.id);
        if (c) {
          const newSos = [];
          SO_KEYS.forEach((letter, idx) => {
            const rad = document.querySelector(`input[name="so_radio_${idx}"]:checked`);
            newSos.push(rad ? rad.value : '-');
          });
          c.sos = newSos;

          if (window.ALL_COURSES) {
            window.ALL_COURSES.forEach(ac => {
              if (ac.code === tr.id) ac.sos = newSos;
            });
          }
        }

      } else if (tr.type === 'so') {
        const selectedPeos = [];
        FLOW_PEO_DEFS.forEach(peo => {
          const chk = document.querySelector(`input[name="peo_chk_${peo.id}"]:checked`);
          if (chk) selectedPeos.push(peo.id);
        });
        peoSoLinks[tr.id] = selectedPeos;
        window.savePeoSoLinks(peoSoLinks);

      } else if (tr.type === 'peo') {
        const selectedGas = [];
        FLOW_GA_DEFS.forEach(ga => {
          const chk = document.querySelector(`input[name="ga_chk_${ga.id}"]:checked`);
          if (chk) selectedGas.push(ga.id);
        });
        peoGaLinks[tr.id] = selectedGas;
        window.savePeoGaLinks(peoGaLinks);

      } else if (tr.type === 'ga') {
        FLOW_PEO_DEFS.forEach(peo => {
          const chk = document.querySelector(`input[name="peo_ga_chk_${peo.id}"]:checked`);
          if (!peoGaLinks[peo.id]) peoGaLinks[peo.id] = [];
          if (chk) {
            if (!peoGaLinks[peo.id].includes(Number(tr.id))) peoGaLinks[peo.id].push(Number(tr.id));
          } else {
            peoGaLinks[peo.id] = peoGaLinks[peo.id].filter(g => g !== Number(tr.id));
          }
        });
        window.savePeoGaLinks(peoGaLinks);
      }

      window.closeFlowLinkEditor();
      if (typeof window.renderFlowGraph === 'function') window.renderFlowGraph();
      if (typeof window.renderObeMatrix === 'function') window.renderObeMatrix();
      if (typeof showToast === 'function') {
        showToast(`✓ Updated relational mappings for ${tr.id}!`);
      }
    };

    function renderObeMatrix() {
      const tbody = document.getElementById('matrixTableBody') || document.getElementById('obe-matrix-tbody');
      if (!tbody) return;

      const activeYr = getActiveObeYear();
      const verStr = getObeVersionString(activeYr);

      const filterCategoryEl = document.getElementById('obe-filter-category');
      const filterYearEl = document.getElementById('obe-filter-year');
      const searchInputEl = document.getElementById('obe-search-input');

      const filterCategory = filterCategoryEl ? filterCategoryEl.value : 'all';
      const filterYear = filterYearEl ? filterYearEl.value : 'all';
      const searchQuery = searchInputEl ? searchInputEl.value.trim().toLowerCase() : '';

      const dataset = (window.OFFICIAL_BASELINE_74_COURSES && window.OFFICIAL_BASELINE_74_COURSES.length > 0)
        ? window.OFFICIAL_BASELINE_74_COURSES
        : (typeof OFFICIAL_BASELINE_74_COURSES !== 'undefined' ? OFFICIAL_BASELINE_74_COURSES : []);

      let filtered = dataset.filter(c => {
        if (filterCategory !== 'all' && c.group !== filterCategory) return false;
        if (filterYear !== 'all' && String(c.year) !== filterYear) return false;
        if (searchQuery) {
          const matchCode = (c.code || '').toLowerCase().includes(searchQuery);
          const matchTitle = (c.title || '').toLowerCase().includes(searchQuery);
          if (!matchCode && !matchTitle) return false;
        }
        return true;
      });

      const countEl = document.getElementById('obe-course-count');
      if (countEl) countEl.textContent = `${filtered.length} courses loaded (OBE v${verStr})`;

      if (filtered.length === 0) {
        tbody.innerHTML = `<tr><td colspan="19" class="p-8 text-center text-slate-400 italic">No courses match the current filter criteria.</td></tr>`;
        return;
      }

      const SO_LABELS = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm'];
      const peoSoLinks = window.getPeoSoLinks() || {};
      const peoGaLinks = window.getPeoGaLinks() || {};

      let rowsHtml = '';
      filtered.forEach((course, idx) => {
        const rowBg = idx % 2 === 0 ? 'bg-white dark:bg-[#111722]' : 'bg-slate-50/60 dark:bg-[#0D131C]';
        const sos = course.sos || ['-','-','-','-','-','-','-','-','-','-','-','-','-'];

        const coursePeos = new Set();
        const courseGas = new Set();

        let cellsHtml = '';
        SO_LABELS.forEach((soLetter, soIdx) => {
          const val = (sos[soIdx] || '-').trim().toUpperCase();
          let badgeClass = 'text-slate-300 dark:text-slate-600 font-light';
          let displayVal = '-';

          if (val === 'I') {
            badgeClass = 'bg-emerald-100 dark:bg-emerald-950/60 text-emerald-800 dark:text-emerald-300 font-bold border border-emerald-300 dark:border-emerald-700 shadow-2xs';
            displayVal = 'I';
            const peos = peoSoLinks[soLetter] || [];
            peos.forEach(p => {
              coursePeos.add(p);
              (peoGaLinks[p] || []).forEach(g => courseGas.add(g));
            });
          } else if (val === 'E') {
            badgeClass = 'bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300 font-bold border border-amber-300 dark:border-amber-700 shadow-2xs';
            displayVal = 'E';
            const peos = peoSoLinks[soLetter] || [];
            peos.forEach(p => {
              coursePeos.add(p);
              (peoGaLinks[p] || []).forEach(g => courseGas.add(g));
            });
          } else if (val === 'D') {
            badgeClass = 'bg-indigo-100 dark:bg-indigo-950/60 text-indigo-800 dark:text-indigo-300 font-bold border border-indigo-300 dark:border-indigo-700 shadow-2xs';
            displayVal = 'D';
            const peos = peoSoLinks[soLetter] || [];
            peos.forEach(p => {
              coursePeos.add(p);
              (peoGaLinks[p] || []).forEach(g => courseGas.add(g));
            });
          }

          cellsHtml += `
            <td class="p-1 text-center border border-slate-200 dark:border-slate-800">
              <button type="button" onclick="cycleObeProgression('${course.code}', ${soIdx})" 
                      title="Click to cycle I -> E -> D -> '-' for SO (${soLetter}) [v${verStr}]"
                      class="w-7 h-7 inline-flex items-center justify-center font-mono text-[11px] rounded-none cursor-pointer hover:ring-2 hover:ring-apc-blue/50 transition-all ${badgeClass}">
                ${displayVal}
              </button>
            </td>
          `;
        });

        const peoListStr = Array.from(coursePeos).sort((a,b)=>a-b).map(p => `P${p}`).join(', ') || '-';
        const gaListStr = Array.from(courseGas).sort((a,b)=>a-b).map(g => `G${g}`).join(', ') || '-';

        rowsHtml += `
          <tr class="${rowBg} hover:bg-blue-50/50 dark:hover:bg-slate-800/40 transition-colors">
            <td class="p-2 font-mono font-bold text-slate-900 dark:text-white border border-slate-200 dark:border-slate-800 text-xs sticky left-0 ${rowBg} z-10 min-w-[100px] shadow-xs">${course.code}</td>
            <td class="p-2 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-800 text-xs font-medium sticky left-[100px] ${rowBg} z-10 min-w-[220px] shadow-xs">${course.title}</td>
            <td class="p-2 font-mono font-bold text-center text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-800 text-xs">${course.units !== undefined ? course.units : 3}</td>
            <td class="p-2 font-mono text-center text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-800 text-xs">Y${course.year} T${course.term}</td>
            ${cellsHtml}
            <td class="p-1.5 font-mono text-[10px] text-center font-bold text-purple-700 dark:text-purple-300 border border-slate-200 dark:border-slate-800 bg-purple-50/30 dark:bg-purple-950/20">${peoListStr}</td>
            <td class="p-1.5 font-mono text-[10px] text-center font-bold text-[#002855] dark:text-[#E5A823] border border-slate-200 dark:border-slate-800 bg-amber-50/30 dark:bg-amber-950/20">${gaListStr}</td>
          </tr>
        `;
      });

      tbody.innerHTML = rowsHtml;
    }

    function cycleObeProgression(courseCode, soIndex) {
      if (typeof isCurriculumLocked === 'function' && isCurriculumLocked()) {
        if (typeof showToast === 'function') showToast('🔒 Locked: Active enrolled batch is read-only. Edits apply to Next Year Batch (2027).');
        return;
      }
      const course = (window.OFFICIAL_BASELINE_74_COURSES || []).find(c => c.code === courseCode);
      if (!course) return;

      if (!course.sos) {
        course.sos = ['-','-','-','-','-','-','-','-','-','-','-','-','-'];
      }

      const cycle = ['-', 'I', 'E', 'D'];
      const current = (course.sos[soIndex] || '-').trim().toUpperCase();
      const nextIdx = (cycle.indexOf(current) + 1) % cycle.length;
      course.sos[soIndex] = cycle[nextIdx];

      // Sync across batches in ALL_COURSES if present
      if (window.ALL_COURSES) {
        window.ALL_COURSES.forEach(c => {
          if (c.code === courseCode && c.sos) {
            c.sos[soIndex] = course.sos[soIndex];
          }
        });
      }

      // Mid-year change automatically increments revision (e.g. 2026 -> 2026.a -> 2026.b)
      const newRev = bumpCurrentObeRevision(`Course ${courseCode} SO mapping changed`);

      renderObeMatrix();
      if (typeof showToast === 'function') {
        const soLetters = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm'];
        showToast(`Updated ${courseCode} SO (${soLetters[soIndex]}) to '${course.sos[soIndex]}' — OBE Revision bumped to ${newRev}`);
      }
    }

    window.getObeConfig = getObeConfig;
    window.getActiveObeYear = getActiveObeYear;
    window.getObeVersionString = getObeVersionString;
    window.setObeActiveYear = setObeActiveYear;
    window.bumpCurrentObeRevision = bumpCurrentObeRevision;
    window.resetCurrentObeRevision = resetCurrentObeRevision;
    window.updateAllObeVersionBadges = updateAllObeVersionBadges;
    window.switchObeTab = switchObeTab;
    window.renderObeMatrix = renderObeMatrix;
    window.cycleObeProgression = cycleObeProgression;
    window.renderPeoSoAlignmentTable = renderPeoSoAlignmentTable;
    window.renderPeoGaAlignmentTable = renderPeoGaAlignmentTable;
    window.renderPeoCards = renderPeoCards;
    window.renderSoCards = renderSoCards;
    window.renderGaCards = renderGaCards;
    window.openEditObeDefinitionModal = openEditObeDefinitionModal;
    window.openEditAllDefinitionsModal = openEditAllDefinitionsModal;
    window.closeEditObeDefinitionModal = closeEditObeDefinitionModal;
    window.onObeDefSelectSwitch = onObeDefSelectSwitch;
    window.handleSaveObeDefinition = handleSaveObeDefinition;
    window.setFlowViewMode = setFlowViewMode;
    window.renderVersioningHistoryView = renderVersioningHistoryView;
    window.switchVhInspectorTab = switchVhInspectorTab;
    window.switchVhDomain = switchVhDomain;
    window.renderVhSoDomain = renderVhSoDomain;
    window.renderVhPeoDomain = renderVhPeoDomain;
    window.renderVhGaDomain = renderVhGaDomain;
    window.renderVhMvvDomain = renderVhMvvDomain;
    window.renderVhCurricDomain = renderVhCurricDomain;

    // Initialize categories, legend, role state, and audit trail on load
    try {
      renderFlowchartLegend();
      populateCategoryDropdowns();
      renderAuditTable();
      switchRole('admin', false);
      applyRolePermissions();
      updateAllObeVersionBadges();
      if (typeof populateCurriculumMapSelect === 'function') populateCurriculumMapSelect();
      if (typeof renderPeoCards === 'function') renderPeoCards();
      if (typeof renderSoCards === 'function') renderSoCards();
      if (typeof renderGaCards === 'function') renderGaCards();
      if (typeof renderPeoSoAlignmentTable === 'function') renderPeoSoAlignmentTable();
      if (typeof renderPeoGaAlignmentTable === 'function') renderPeoGaAlignmentTable();
      if (typeof renderVersioningHistoryView === 'function') renderVersioningHistoryView();
      if (typeof renderFlowGraph === 'function') renderFlowGraph();
    } catch (e) {
      console.warn('Initial setup warning:', e);
    }


